def secure_name(name):
    keep="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-"
    return ''.join(ch if ch in keep else '_' for ch in name)
    
    
def clean_multiline_text(text):
    if not text:
        return ""

    lines = str(text).replace("\r\n", "\n").replace("\r", "\n").split("\n")

    cleaned_lines = []

    for line in lines:
        cleaned_lines.append(line.strip())

    # Remove empty lines at the start
    while cleaned_lines and cleaned_lines[0] == "":
        cleaned_lines.pop(0)

    # Remove empty lines at the end
    while cleaned_lines and cleaned_lines[-1] == "":
        cleaned_lines.pop()

    return "\n".join(cleaned_lines)
    
    
def normalise_name_for_match(name):
    """
    Clean a name so that matching is easier.
    This removes symbols, extra spaces, and ignores capital letters.
    """
    if not name:
        return ""

    import re

    cleaned = str(name).lower().strip()

    # Remove punctuation and symbols, but keep letters, numbers, and spaces
    cleaned = re.sub(r"[^a-z0-9\s]", " ", cleaned)

    # Convert multiple spaces into one space
    cleaned = " ".join(cleaned.split())

    return cleaned


def name_tokens_for_match(name):
    """
    Turns a full name into separate clean words.

    Example:
    'Radebe   Fumane Mthandeni'
    becomes:
    ['radebe', 'fumane', 'mthandeni']
    """
    cleaned = normalise_name_for_match(name)

    if not cleaned:
        return []

    return [x for x in cleaned.split() if x]


def name_match_score(award_name, portal_name):
    """
    Gives a match score between the name from the awards list
    and the name stored in the portal.

    Handles:
    - name then surname
    - surname then name
    - middle names
    - extra spaces
    - different capital letters
    """

    award_tokens = name_tokens_for_match(award_name)
    portal_tokens = name_tokens_for_match(portal_name)

    if not award_tokens or not portal_tokens:
        return 0

    award_set = set(award_tokens)
    portal_set = set(portal_tokens)

    common = award_set.intersection(portal_set)

    # Exact cleaned name match
    if normalise_name_for_match(award_name) == normalise_name_for_match(portal_name):
        return 100

    # Same words, but different order
    # Example: "Radebe Fumane" and "Fumane Radebe"
    if award_set == portal_set:
        return 95

    # All awards name words exist inside portal name
    # Example: award = "Fumane Radebe", portal = "Fumane Mthandeni Radebe"
    if award_set.issubset(portal_set):
        return 90

    # All portal name words exist inside award name
    if portal_set.issubset(award_set):
        return 88

    # First and last words match in the same order
    if len(award_tokens) >= 2 and len(portal_tokens) >= 2:
        award_first = award_tokens[0]
        award_last = award_tokens[-1]
        portal_first = portal_tokens[0]
        portal_last = portal_tokens[-1]

        if award_first == portal_first and award_last == portal_last:
            return 85

        # First and last words match in reverse order
        # Example: award = "Radebe Fumane", portal = "Fumane Radebe"
        if award_first == portal_last and award_last == portal_first:
            return 82

    # At least two name words match
    if len(common) >= 2:
        return 75

    # Single-name cases like "Luyanda"
    if len(award_tokens) == 1 and award_tokens[0] in portal_set:
        return 55

    return 0    


def parse_awards_student_list(raw_text):
    """
    Parses pasted award list data.

    Supports lines like:
    1   Fumane Mthandeni Radebe   8   Overall Top 1 + EMS 1st
    2   Letlotlo Modise           8   EMS 2nd + Most Active

    Returns a list of dictionaries:
    {
        "list_no": "1",
        "learner_name": "...",
        "grade": "8",
        "award_category": "..."
    }
    """

    if not raw_text:
        return []

    rows = []

    text = str(raw_text).replace("\r\n", "\n").replace("\r", "\n")

    for line in text.split("\n"):
        line = line.strip()

        if not line:
            continue

        # Skip headings or title lines
        lower = line.lower()
        if (
            "ebta term" in lower
            or "complete student list" in lower
            or lower.startswith("#")
            or "learner name" in lower
            or "award category" in lower
        ):
            continue

        # Prefer tab-separated data
        parts = [p.strip() for p in line.split("\t") if p.strip()]

        # If pasted spaces instead of tabs, try a softer split
        if len(parts) < 4:
            import re
            parts = re.split(r"\s{2,}", line)
            parts = [p.strip() for p in parts if p.strip()]

        # Expected:
        # number | learner name | grade | award category
        if len(parts) >= 4 and parts[0].isdigit():
            rows.append({
                "list_no": parts[0],
                "learner_name": parts[1],
                "grade": parts[2],
                "award_category": " ".join(parts[3:])
            })
            continue

        # Fallback for lines like:
        # 1 Fumane Mthandeni Radebe 8 Overall Top 1 + EMS 1st
        import re
        m = re.match(r"^(\d+)\s+(.+?)\s+(8|9|10|11|12|13)\s+(.+)$", line)

        if m:
            rows.append({
                "list_no": m.group(1).strip(),
                "learner_name": m.group(2).strip(),
                "grade": m.group(3).strip(),
                "award_category": m.group(4).strip()
            })

    return rows
    
    

ALLOWED_REPORT_EXTENSIONS = {'.pdf', '.png', '.jpg', '.jpeg', '.doc', '.docx'}

def is_valid_report(filename):
    ext = os.path.splitext(filename.lower())[1]
    return ext in ALLOWED_REPORT_EXTENSIONS

ALLOWED_PROFILE_PIC_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.webp'}

def is_valid_profile_picture(filename):
    ext = os.path.splitext(filename.lower())[1]
    return ext in ALLOWED_PROFILE_PIC_EXTENSIONS

ALLOWED_APPLICATION_EXTENSIONS = {'.pdf', '.doc', '.docx', '.png', '.jpg', '.jpeg'}

def is_valid_application_file(filename):
    if not filename:
        return False

    ext = os.path.splitext(filename.lower())[1]
    return ext in ALLOWED_APPLICATION_EXTENSIONS


def save_application_file(file, applicant_name, label):
    if not file or not file.filename:
        return None, None

    if not is_valid_application_file(file.filename):
        return None, None

    ext = os.path.splitext(file.filename.lower())[1]
    safe_applicant = secure_name(applicant_name)
    safe_label = secure_name(label)

    folder = APPLICATIONS_DIR / safe_applicant
    folder.mkdir(parents=True, exist_ok=True)

    filename = f"{safe_applicant}_{safe_label}_{int(time.time())}{ext}"
    file_path = folder / filename

    file.save(file_path)

    return str(file_path), filename


def save_management_application_file(file, applicant_name, role_name, label):
    if not file or not file.filename:
        return None, None

    if not is_valid_application_file(file.filename):
        return None, None

    ext = os.path.splitext(file.filename.lower())[1]
    safe_applicant = secure_name(applicant_name)
    safe_role = secure_name(role_name)
    safe_label = secure_name(label)

    folder = APPLICATIONS_DIR / "management" / safe_role / safe_applicant
    folder.mkdir(parents=True, exist_ok=True)

    filename = f"{safe_applicant}_{safe_role}_{safe_label}_{int(time.time())}{ext}"
    file_path = folder / filename

    file.save(file_path)

    return str(file_path), filename


def normalize_phone(phone: str, phone_type: str = "SA", strict: bool = False) -> str:

    if not phone:
        return ""

    phone = str(phone).strip()
    phone = phone.replace(" ", "").replace("-", "").replace("(", "").replace(")", "")

    digits = ''.join(ch for ch in phone if ch.isdigit())

    # INTERNATIONAL
    if phone_type == "INT":
        if phone.startswith("+"):
            return "+" + digits
        return "+" + digits

    # SOUTH AFRICA
    if phone.startswith("+27") and len(digits) == 11:
        return "+27" + digits[-9:]

    if digits.startswith("27") and len(digits) == 11:
        return "+27" + digits[2:]

    if len(digits) == 10 and digits.startswith("0"):
        return "+27" + digits[1:]

    if strict:
        raise ValueError("South African numbers must be 10 digits starting with 0.")

    return ""
    
def phone_variants(phone: str):
    """
    Generate all possible phone variants so login works
    regardless of format entered.
    Supports:
    0821234567
    +27821234567
    27821234567
    international numbers
    """

    if not phone:
        return []

    raw = str(phone).strip()

    # remove spaces, brackets, dashes
    clean = raw.replace(" ", "").replace("-", "").replace("(", "").replace(")", "")

    # digits only
    digits = ''.join(ch for ch in clean if ch.isdigit())

    variants = set()

    # always include original clean input
    variants.add(clean)

    # include digits-only version
    if digits:
        variants.add(digits)
        variants.add("+" + digits)

    # South Africa conversions

    # 0821234567 → 27821234567 and +27821234567
    if digits.startswith("0") and len(digits) == 10:
        variants.add("27" + digits[1:])
        variants.add("+27" + digits[1:])

    # 27821234567 → 0821234567 and +27821234567
    elif digits.startswith("27") and len(digits) == 11:
        variants.add("0" + digits[2:])
        variants.add("+27" + digits[2:])

    # +27821234567 → 27821234567 and 0821234567
    if clean.startswith("+") and digits.startswith("27") and len(digits) == 11:
        variants.add(digits)
        variants.add("0" + digits[2:])

    return list(variants)


def gen_pin(existing):
    while True:
        p = f"{random.randint(0,99999):05d}"
        if p not in existing: return p

def is_valid_pin(pin): return len(pin)==5 and pin.isdigit()

def pin_in_use(conn, pin):
    cur = conn.cursor()
    cur.execute("SELECT 1 FROM students WHERE pin=? LIMIT 1",(pin,))
    if cur.fetchone(): return True
    cur.execute("SELECT 1 FROM tutors WHERE pin=? LIMIT 1",(pin,))
    return cur.fetchone() is not None

def b64url_encode(b): return base64.urlsafe_b64encode(b).decode('ascii').rstrip('=')
def b64url_decode(s):
    pad = '=' * (-len(s)%4)
    return base64.urlsafe_b64decode(s+pad)

def month_last_day(year:int, month:int) -> int:
    return calendar.monthrange(year, month)[1]

def rating_window_open(current_month: str) -> bool:
    """Open from the 24th to the last day of current_month (server date)."""
    today = datetime.date.today()
    try:
        y, m = map(int, current_month.split('-'))
    except Exception:
        return False
    last = month_last_day(y, m)
    if today.year == y and today.month == m and 24 <= today.day <= last:
        return True
    return False
        

def enrollment_exists(conn, student_id, subject_id, month):
    cur = conn.cursor()
    cur.execute(
        """
        SELECT 1 FROM enrollments
        WHERE student_id=? AND subject_id=? AND month=?
        LIMIT 1
        """,
        (student_id, subject_id, month)
    )
    return cur.fetchone() is not None
    
    
    
def is_first_time_student(conn, student_id):
    """
    Returns True if the student has no previous enrollment records.
    This is used to make referral points count for new students only.
    """
    cur = conn.cursor()

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM enrollments
        WHERE student_id=?
    """, (student_id,))

    row = cur.fetchone()

    return (row["c"] or 0) == 0


def pretty_month_label(month_str: str) -> str:
    """Convert 'YYYY-MM' to 'Month YYYY' (e.g., '2025-10' -> 'October 2025')."""
    try:
        y, m = map(int, month_str.split('-')[:2])
        return datetime.date(y, m, 1).strftime('%B %Y')
    except Exception:
        return month_str
        
        
TERMS = [
    ("T1", "Term 1"),
    ("T2", "Term 2"),
    ("T3", "Term 3"),
    ("T4", "Term 4"),
]


def make_term_key(year, term_code):
    """
    Stores term marks in the existing aqm_student_marks.month column.
    Example: 2026 + T1 = 2026-T1
    """
    year = str(year).strip()
    term_code = str(term_code).strip().upper()

    if term_code not in ["T1", "T2", "T3", "T4"]:
        term_code = "T1"

    if not year.isdigit():
        year = str(datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).year)

    return f"{year}-{term_code}"


def split_term_key(term_key):
    """
    Converts 2026-T1 into year=2026 and term_code=T1.
    """
    try:
        year, term_code = str(term_key).split("-", 1)
        term_code = term_code.upper()
        if term_code not in ["T1", "T2", "T3", "T4"]:
            term_code = "T1"
        return year, term_code
    except Exception:
        return str(datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).year), "T1"


def term_label(term_key):
    """
    Converts 2026-T1 into 2026 Term 1.
    """
    year, term_code = split_term_key(term_key)

    labels = {
        "T1": "Term 1",
        "T2": "Term 2",
        "T3": "Term 3",
        "T4": "Term 4",
    }

    return f"{year} {labels.get(term_code, 'Term 1')}"

        
def record_material_view(material_id, student_id):
    conn = get_db()
    cur = conn.cursor()

    now = now_utc_iso()
    ip = request.remote_addr
    ua = request.headers.get("User-Agent", "")[:300]

    cur.execute("""
        INSERT INTO material_views(
            material_id,
            student_id,
            first_viewed_at,
            last_viewed_at,
            view_count,
            ip_address,
            user_agent
        )
        VALUES(?,?,?,?,?,?,?)
        ON CONFLICT(material_id, student_id)
        DO UPDATE SET
            last_viewed_at = excluded.last_viewed_at,
            view_count = material_views.view_count + 1,
            ip_address = excluded.ip_address,
            user_agent = excluded.user_agent
    """, (
        material_id,
        student_id,
        now,
        now,
        1,
        ip,
        ua
    ))

    conn.commit()
    conn.close()


def expected_class_dates_for_subject(cur, subject_id, tutor_id, month, expected_classes):
    """
    Returns expected class dates for a subject in a month based on the tutor's active session day.
    EBTA rule:
    Grade 8 to Grade 12 = 4 classes per month
    Grade 13 = 6 classes per month
    """

    try:
        year, month_num = map(int, month.split("-"))
    except:
        return []

    cur.execute("""
        SELECT day_of_week
        FROM sessions
        WHERE subject_id = ?
          AND tutor_id = ?
          AND active = 1
        ORDER BY day_of_week, start_time
    """, (subject_id, tutor_id))

    session_rows = cur.fetchall()

    if not session_rows:
        return []

    session_days = {r["day_of_week"] for r in session_rows}

    last_day = calendar.monthrange(year, month_num)[1]
    expected_dates = []

    for day in range(1, last_day + 1):
        d = datetime.date(year, month_num, day)

        # Python weekday: Monday=0, Sunday=6
        # Your system DOW: Sunday=0, Monday=1, ..., Saturday=6
        system_day = (d.weekday() + 1) % 7

        if system_day in session_days:
            expected_dates.append(d.isoformat())

    # Very important:
    # Only return the number of dates allowed by EBTA monthly rule.
    return expected_dates[:expected_classes]



# ===================== Notifications (Email & SMS) ==============
def send_email_notification(to_email: str, subject: str, body: str):
    # Best-effort email sender.
    # Uses SMTP settings from environment if configured, otherwise logs into the messages table.
    # Env vars for real sending:
    #   EBTA_SMTP_HOST, EBTA_SMTP_PORT, EBTA_SMTP_USER, EBTA_SMTP_PASS, EBTA_SMTP_FROM (optional, falls back to user).
    if not to_email:
        return
    host = os.environ.get("EBTA_SMTP_HOST")
    port = int(os.environ.get("EBTA_SMTP_PORT", "587"))
    user = os.environ.get("EBTA_SMTP_USER")
    pwd = os.environ.get("EBTA_SMTP_PASS")
    sender = os.environ.get("EBTA_SMTP_FROM", user)

    # If SMTP is not configured, just log the outgoing email in the admin Messages page
    if not (host and user and pwd and sender):
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"TO:{to_email} | SUBJECT:{subject} | BODY:{body}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("email_log", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except Exception:
            pass
        return

    try:
        import smtplib
        from email.message import EmailMessage



        msg = EmailMessage()
        msg["Subject"] = subject
        msg["From"] = sender
        msg["To"] = to_email
        msg.set_content(body)

        with smtplib.SMTP(host, port, timeout=30) as s:
            s.ehlo()
            s.starttls()
            s.ehlo()
            s.login(user, pwd)
            s.send_message(msg)
    except Exception as e:
        # Log error so admin can see what went wrong
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"TO:{to_email} | SUBJECT:{subject} | ERROR:{e}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("email_error", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except Exception:
            pass


def send_sms_notification(to_phone: str, body: str):
    # Best-effort SMS sender with automatic SA phone normalization

    if not to_phone:
        return

    # --- Normalize South African phone number ---
    phone = str(to_phone).strip()

    # remove spaces, dashes, brackets
    phone = phone.replace(" ", "").replace("-", "").replace("(", "").replace(")", "")

    # convert 0821234567 → +27821234567
    if phone.startswith("0") and len(phone) == 10:
        phone = "+27" + phone[1:]

    # convert 27821234567 → +27821234567
    elif phone.startswith("27") and len(phone) == 11:
        phone = "+" + phone

    # already correct format
    elif phone.startswith("+"):
        pass

    else:
        # invalid format → log error
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"INVALID_PHONE:{to_phone}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("sms_error", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except:
            pass
        return  

    to_phone = phone

    account_sid = os.environ.get("EBTA_TWILIO_SID")
    auth_token = os.environ.get("EBTA_TWILIO_TOKEN")
    from_number = os.environ.get("EBTA_TWILIO_FROM")

    # If Twilio not configured, log SMS
    if not (account_sid and auth_token and from_number):
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"TO:{to_phone} | BODY:{body}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("sms_log", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except:
            pass
        return

    # Send via Twilio
    try:
        from twilio.rest import Client

        client = Client(account_sid, auth_token)

        client.messages.create(
            from_=from_number,
            to=to_phone,
            body=body
        )

        # optional success log
        conn = get_db()
        cur = conn.cursor()
        payload = f"SENT TO:{to_phone}"
        cur.execute(
            "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
            ("sms_sent", payload, now_utc_iso()),
        )
        conn.commit()
        conn.close()

    except Exception as e:
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"TO:{to_phone} | ERROR:{e}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("sms_error", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except:
            pass

