@app.post('/tutor/upload')
def tutor_upload():
    r=require_tutor()
    if r: return r
    tid=is_tutor(); month = get_active_month('tutor')
    subject_id=request.form.get('subject_id','').strip()
    title=request.form.get('title','').strip()
    youtube=request.form.get('youtube','').strip()
    file=request.files.get('file')
    is_assignment=1 if request.form.get('is_assignment')=='on' else 0
    due=request.form.get('due','').strip() or None
    max_points = request.form.get('max_points','').strip()
    try:
        max_points = int(max_points) if max_points else 100
    except Exception:
        max_points = 100
    if max_points < 1: max_points = 1
    if max_points > 1000: max_points = 1000
    if not (subject_id and title): return page("Error", card_msg("Subject and title required."))

    conn=get_db(); cur=conn.cursor()
    cur.execute("""
        SELECT s.uploads_locked
        FROM tutor_subjects ts
        JOIN subjects s ON s.id = ts.subject_id
        WHERE ts.tutor_id=? AND ts.subject_id=?
    """, (tid, subject_id))

    row = cur.fetchone()

    if not row:
        conn.close()
        return page("Error", card_msg("This subject is not assigned to you."))

    if row["uploads_locked"] == 1:
        conn.close()
        return page(
            "Uploads Locked",
            card_msg("Uploads and assignments are currently locked for this subject. Contact Admin.")
        )

    file_path=None
    if file and file.filename:
        safe=f"{int(datetime.datetime.now().timestamp())}_{secure_name(file.filename)}"
        dest=MATERIALS_DIR/safe; file.save(dest); file_path=f"/materials-files/{safe}"
    if not (file_path or youtube):
        conn.close(); return page("Error", card_msg("Attach a file or provide a YouTube link."))

    now=now_utc_iso()
    kind = 'assignment' if is_assignment else ('file' if file_path else 'youtube')
    cur.execute("""INSERT INTO materials(subject_id,tutor_id,month,title,kind,file_path,youtube_url,created_at,is_assignment,due_date,max_points)
                VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                (subject_id, tid, month, title, kind, file_path, youtube if youtube else None, now, is_assignment, due, max_points))
    conn.commit(); conn.close()
    return redirect(url_for('tutor_home'))
    
    
@app.post('/tutor/assignment/<int:mid>/upload-marked/<int:sid>')
def tutor_upload_marked_script(mid, sid):

    r = require_tutor()
    if r: return r

    tid = is_tutor()
    f = request.files.get("marked_file")

    if not f or not f.filename:
        return redirect(url_for("tutor_assignment_manage", mid=mid))

    conn = get_db()
    cur = conn.cursor()

    # Make sure this assignment belongs to the logged-in tutor
    cur.execute("""
        SELECT id
        FROM materials
        WHERE id = ?
          AND tutor_id = ?
          AND (is_assignment = 1 OR kind = 'assignment')
    """, (mid, tid))

    assignment = cur.fetchone()

    if not assignment:
        conn.close()
        return page("Error", card_msg("Assignment not found or not allowed."))

    # Make sure the learner actually submitted
    cur.execute("""
        SELECT id
        FROM submissions
        WHERE material_id = ?
          AND student_id = ?
    """, (mid, sid))

    sub = cur.fetchone()

    if not sub:
        conn.close()
        return page("Error", card_msg("This learner has not submitted yet."))

    filename = secure_name(f.filename)
    marked_filename = f"marked_{mid}_{sid}_{int(time.time())}_{filename}"
    path = SUBMISSIONS_DIR / marked_filename

    f.save(path)

    cur.execute("""
        UPDATE submissions
        SET marked_file_path = ?,
            evaluated_at = ?
        WHERE id = ?
    """, (str(path), now_utc_iso(), sub["id"]))

    conn.commit()
    conn.close()

    return redirect(url_for("tutor_assignment_manage", mid=mid, saved=1))
    

@app.post('/tutor/materials/<int:mid>/delete')
def tutor_delete_material(mid:int):
    r=require_tutor()
    if r: return r
    tid=is_tutor()
    conn=get_db(); cur=conn.cursor()
    cur.execute("SELECT tutor_id,created_at FROM materials WHERE id=?", (mid,))
    m=cur.fetchone()
    if not m or m['tutor_id']!=tid:
        conn.close(); return page("Error", card_msg("Not found."))
    try:
        created=datetime.datetime.fromisoformat(m['created_at'])
        if (datetime.datetime.now(datetime.timezone.utc)-created) > datetime.timedelta(hours=24):
            conn.close(); return page("Locked", card_msg("You can only delete within 24 hours."))
    except Exception:
        pass
    cur.execute("DELETE FROM materials WHERE id=?", (mid,))
    conn.commit(); conn.close()
    return redirect(url_for('tutor_home'))

# Tutor: manage one assignment (submissions + grading)
@app.get('/tutor/assignment/<int:mid>')
def tutor_assignment_manage(mid: int):

    r = require_tutor()
    if r: return r

    tid = is_tutor()
    saved = request.args.get('saved')

    conn = get_db()
    cur = conn.cursor()

    # Confirm this assignment belongs to this tutor
    cur.execute("""
        SELECT m.*, s.name AS subject_name, s.grade
        FROM materials m
        JOIN subjects s ON s.id = m.subject_id
        WHERE m.id = ?
          AND m.tutor_id = ?
    """, (mid, tid))

    m = cur.fetchone()

    if not m:
        conn.close()
        return page("Not found", card_msg("Assignment not found."))

    total = m['max_points'] if m['max_points'] else 100

    # Active students in this subject/month
    month = get_active_month('tutor')

    cur.execute("""
        SELECT st.id, st.full_name
        FROM enrollments e
        JOIN students st ON st.id = e.student_id
        WHERE e.subject_id = ?
          AND e.month = ?
          AND e.status = 'ACTIVE'
        ORDER BY st.full_name
    """, (m['subject_id'], month))

    studs = cur.fetchall()
    rows = []

    for st in studs:

        cur.execute("""
            SELECT 
                id,
                file_path,
                submitted_at,
                mark,
                feedback,
                marked_file_path,
                is_published
            FROM submissions
            WHERE material_id = ?
              AND student_id = ?
        """, (mid, st['id']))

        sub = cur.fetchone()

        if sub:

            file_exists = sub['file_path'] and os.path.exists(sub['file_path'])

            if file_exists:
                view_section = f"""
                <a class='btn success mini'
                   target='_blank'
                   href='/tutor/view_submission/{sub['id']}'>
                    View Submission
                </a>
                """
            else:
                view_section = """
                <span class='mini' style="color:#b91c1c;font-weight:600">
                    File missing
                </span>
                """

            marked_script_btn = ""

            if sub["marked_file_path"] and os.path.exists(sub["marked_file_path"]):
                marked_script_btn = f"""
                <a class="btn success mini"
                   target="_blank"
                   href="/tutor/view_marked_script/{mid}/{st['id']}">
                    View Marked Script
                </a>
                """

            upload_marked_form = f"""
            <form method="post"
                  action="/tutor/assignment/{mid}/upload-marked/{st['id']}"
                  enctype="multipart/form-data"
                  style="margin-top:8px">

                <input type="file"
                       name="marked_file"
                       accept=".pdf,.png,.jpg,.jpeg,.doc,.docx"
                       required
                       class="mini">

                <button class="btn mini success" style="margin-top:6px">
                    Upload Marked Script
                </button>
            </form>
            """

            mark = '' if sub['mark'] is None else str(sub['mark'])

            published_status = (
                "<span class='chip active'>Published</span>"
                if sub["is_published"] == 1
                else "<span class='chip pending'>Not Published</span>"
            )

            rows.append(f"""
            <tr>
                <td>
                    {st['full_name']}
                    <div class="mini muted" style="margin-top:4px">
                        {published_status}
                    </div>
                </td>

                <td style="min-width:260px">
                    <div style="display:flex;flex-direction:column;gap:8px">
                        {view_section}
                        {marked_script_btn}
                        {upload_marked_form}

                        <div class='mini muted'>
                            Submitted: {sub['submitted_at'][:16].replace('T',' ')}
                        </div>
                    </div>
                </td>

                <td>
                    <form method='post'
                          action='{url_for('tutor_assignment_grade', mid=mid, sid=st['id'])}'
                          class='inlineform'>

                        <input type='number'
                               name='mark'
                               min='0'
                               max='{total}'
                               placeholder='0..{total}'
                               value='{mark if mark else ""}'
                               style='width:100px'>

                        <input name='feedback'
                               placeholder='Feedback'
                               value='{escape(sub['feedback'] or "")}'>

                        <button class='btn mini'>
                            Save
                        </button>
                    </form>
                </td>
            </tr>
            """)

        else:
            rows.append(f"""
            <tr>
                <td>{st['full_name']}</td>
                <td><span class='muted'>No submission</span></td>
                <td>—</td>
            </tr>
            """)

    table = (
        "<div class='empty'>No students.</div>"
        if not rows
        else f"""
        <div class='scroll-x'>
            <table>
                <thead>
                    <tr>
                        <th>Student</th>
                        <th>Submission / Marked Script</th>
                        <th>Grade (0..{total})</th>
                    </tr>
                </thead>
                <tbody>
                    {''.join(rows)}
                </tbody>
            </table>
        </div>
        """
    )

    conn.close()

    js_alert = "<script>showPopup('Grade saved', 'success');</script>" if saved else ""

    body = fr"""
    <a class='links' href='{url_for('tutor_home')}'>← Back</a>

    <section class='grid'>
        <div class='card'>
            <h1>{m['title']}</h1>

            <p class='muted'>
                {grade_label(m['grade'])} — {m['subject_name']}
                • Due: {m['due_date'] or '—'}
                • Total: {total}
            </p>

            <div class="card soft" style="margin-top:10px;border-left:5px solid #f59e0b">
                <form method="post"
                      action="{url_for('tutor_extend_due_date', mid=mid)}"
                      class="inlineform"
                      style="display:flex;gap:10px;align-items:end;flex-wrap:wrap">

                    <div>
                        <label class="mini muted">Extend due date</label>
                        <input type="date"
                               name="due_date"
                               value="{m['due_date'] or ''}"
                               required>
                    </div>

                    <button class="btn success mini">
                        Update Due Date
                    </button>
                </form>
            </div>

            <div style="margin:10px 0;">
                <form method="post" action="{url_for('publish_all_marks', mid=mid)}">
                    <button class="btn success">
                        Publish All Marks
                    </button>
                </form>
            </div>

            {table}
        </div>
    </section>
    """

    return page("Manage Assignment", body, extra_js=js_alert)
    
    
@app.get('/tutor/view_marked_script/<int:mid>/<int:sid>')
def tutor_view_marked_script(mid, sid):

    r = require_tutor()
    if r: return r

    tid = is_tutor()

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT sub.marked_file_path
        FROM submissions sub
        JOIN materials m ON m.id = sub.material_id
        WHERE sub.material_id = ?
          AND sub.student_id = ?
          AND m.tutor_id = ?
          AND sub.marked_file_path IS NOT NULL
    """, (mid, sid, tid))

