@app.post('/admin/students/<int:sid>/delete')
@require_high_admin
def admin_student_delete(sid: int):
    r = require_admin()
    if r:
        return r
        
    if not is_high_admin():
        return page("Access Denied", card_msg("You do not have permission to perform this action."))

    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute("BEGIN")

        # 1. Delete attendance
        cur.execute("DELETE FROM attendance WHERE student_id=?", (sid,))

        # 2. Delete submissions
        cur.execute("DELETE FROM submissions WHERE student_id=?", (sid,))

        # 3. Delete lesson ratings
        cur.execute("DELETE FROM lesson_ratings WHERE student_id=?", (sid,))

        # 4. Delete enrollment files (important)
        cur.execute("""
            DELETE FROM enrollment_files
            WHERE enrollment_id IN (
                SELECT id FROM enrollments WHERE student_id=?
            )
        """, (sid,))

        # 5. Delete payments
        cur.execute("""
            DELETE FROM payments
            WHERE enrollment_id IN (
                SELECT id FROM enrollments WHERE student_id=?
            )
        """, (sid,))

        # 6. Delete enrollments
        cur.execute("DELETE FROM enrollments WHERE student_id=?", (sid,))

        # 7. Delete registrations
        cur.execute("DELETE FROM registrations WHERE student_id=?", (sid,))

        # 8. Delete messages
        cur.execute("""
            DELETE FROM direct_messages
            WHERE (from_role='student' AND from_id=?)
               OR (to_role='student' AND to_id=?)
        """, (sid, sid))

        # 9. Finally delete student
        cur.execute("DELETE FROM students WHERE id=?", (sid,))

        conn.commit()
    except Exception as e:
        conn.rollback()
        raise
    finally:
        conn.close()

    return redirect(url_for('admin_students'))


@app.get('/admin/reports')
def admin_reports():

    r = require_admin()
    if r: return r

    search = request.args.get("search", "").strip()
    grade_filter = request.args.get("grade", "").strip()
    term_filter = request.args.get("term", "").strip()

    try:
        page_num = int(request.args.get("page", 1))
    except:
        page_num = 1

    if page_num < 1:
        page_num = 1

    per_page = 20
    offset = (page_num - 1) * per_page

    where_parts = []
    params = []

    if search:
        where_parts.append("s.full_name LIKE ?")
        params.append(f"%{search}%")

    if grade_filter:
        where_parts.append("sr.grade = ?")
        params.append(grade_filter)
        
    if term_filter:
        where_parts.append("sr.term = ?")
        params.append(term_filter)

    where_sql = ""
    if where_parts:
        where_sql = "WHERE " + " AND ".join(where_parts)

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT DISTINCT grade FROM student_reports WHERE grade IS NOT NULL ORDER BY grade")
    grades = cur.fetchall()

    cur.execute(f"""
        SELECT COUNT(*) AS total
        FROM student_reports sr
        JOIN students s ON s.id = sr.student_id
        {where_sql}
    """, params)

    total_reports = cur.fetchone()["total"]

    total_pages = (total_reports + per_page - 1) // per_page

    if total_pages == 0:
        total_pages = 1

    if page_num > total_pages:
        page_num = total_pages

    offset = (page_num - 1) * per_page

    cur.execute(f"""
        SELECT 
            sr.*, 
            s.full_name,

            (
                SELECT COUNT(DISTINCT e.month)
                FROM enrollments e
                WHERE e.student_id = sr.student_id
                AND e.status = 'ACTIVE'
            ) AS months_active

        FROM student_reports sr
        JOIN students s ON s.id = sr.student_id
        {where_sql}
        ORDER BY sr.upload_date DESC
        LIMIT ? OFFSET ?
    """, (*params, per_page, offset))

    rows = cur.fetchall()
    conn.close()

    grade_options = '<option value="">All Grades</option>'

    for g in grades:
        selected = "selected" if grade_filter == g["grade"] else ""
        grade_options += f"""
        <option value="{g['grade']}" {selected}>{grade_label(g['grade'])}</option>
        """

    term_options = '<option value="">All Terms</option>'

    for term in ["Term 1", "Term 2", "Term 3", "Term 4"]:
        selected = "selected" if term_filter == term else ""
        term_options += f"""
        <option value="{term}" {selected}>{term}</option>
        """

    html = ""

    for r0 in rows:
        html += f"""
        <tr>
            <td>{r0['full_name']}</td>
            <td>{r0['grade']}</td>
            <td>
                <span class='chip'>
                    {r0['months_active'] or 0} months
                </span>
            </td>
            <td>{r0['term'] or '—'}</td>
            <td>{r0['file_name']}</td>
            <td>{format_datetime(r0['upload_date'])}</td>
            <td style="display:flex; gap:6px">

                <a class='btn mini' target='_blank'
                   href='/admin/view_report/{r0["id"]}'>View</a>
                   
                <a class='btn mini secondary'
                   href='/admin/download_report/{r0["id"]}'>Download</a>

                {"" if not is_high_admin() else f"""
                <form method='post'
                      action='/admin/delete_report/{r0["id"]}'
                      onsubmit="return confirm('Delete this report?');">
                    <button class='btn mini danger'>Delete</button>
                </form>
                """}

            </td>
        </tr>
        """

    query_base = f"search={search}&grade={grade_filter}&term={term_filter}"
    download_zip_url = f"/admin/download_reports_zip?{query_base}"

    pagination_html = ""

    if total_reports > per_page:
        prev_link = ""
        next_link = ""

        if page_num > 1:
            prev_link = f"""
            <a class='btn mini secondary'
               href='/admin/reports?{query_base}&page={page_num - 1}'>
                ← Previous
            </a>
            """

        if page_num < total_pages:
            next_link = f"""
            <a class='btn mini secondary'
               href='/admin/reports?{query_base}&page={page_num + 1}'>
                Next →
            </a>
            """

        pagination_html = f"""
        <div class='toolbar' style='margin-top:12px;align-items:center'>
            {prev_link}
            <span class='chip'>Page {page_num} of {total_pages}</span>
            {next_link}
        </div>
        """

    body = f"""
    {admin_nav()}
    <div class='card'>
        <h2>Student Reports</h2>

        <div class="stats" style="margin-bottom:12px">
            <div class="stat">
                <div class="k">{total_reports}</div>
                <div class="t">Matching Reports</div>
            </div>
        </div>

        <form method="get"
              style="display:grid;grid-template-columns:2fr 1fr 1fr auto auto;gap:10px;margin-bottom:14px;align-items:end">

            <div>
                <label>Search student</label>
                <input name="search"
                       value="{search}"
                       placeholder="Search by student name">
            </div>

            <div>
                <label>Grade</label>
                <select name="grade">
                    {grade_options}
                </select>
            </div>
            
            <div>
                <label>Term</label>
                <select name="term">
                    {term_options}
                </select>
            </div>

            <button class="btn success">Apply</button>

            <a class="btn secondary" href="/admin/reports">Reset</a>
        </form>
        
        <div class="toolbar">
            <a class="btn mini success" href="{download_zip_url}">
                Download Reports as ZIP
            </a>

            {"" if not is_high_admin() else """
            <a class="btn mini secondary" href="/admin/reports/term-cleanup">
                Term Cleanup
            </a>
            """}
        </div>

        <div class="mini muted" style="margin-bottom:10px">
            Showing {len(rows)} of {total_reports} reports.
        </div>

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Student</th>
                        <th>Grade</th>
                        <th>Months Active</th>
                        <th>Term</th>
                        <th>File</th>
                        <th>Date</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    {html or "<tr><td colspan='7'>No reports found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_html}
    </div>
    """

    return page("Student Reports", body)


@app.get('/admin/reports/term-cleanup')
@require_high_admin
def admin_reports_term_cleanup():

    r = require_admin()
    if r: return r

    conn = get_db()
    cur = conn.cursor()

    # Reports with no term yet
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM student_reports
        WHERE term IS NULL
           OR TRIM(term) = ''
    """)
    missing_term_count = cur.fetchone()["c"] or 0

    # Current Term 1 reports
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM student_reports
        WHERE term = 'Term 1'
    """)
    term_one_count = cur.fetchone()["c"] or 0

    # Students with more than one Term 1/blank report
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM (
            SELECT student_id
            FROM student_reports
            WHERE term = 'Term 1'
               OR term IS NULL
               OR TRIM(term) = ''
            GROUP BY student_id
            HAVING COUNT(*) > 1
        )
    """)
    duplicate_students_count = cur.fetchone()["c"] or 0

    conn.close()

    body = f"""
    {admin_nav()}

    <section class="card">
        <h1>Reports Term Cleanup</h1>

        <p class="muted">
            Use this once-off tool to update older reports that were uploaded before the Term 1, Term 2, Term 3 and Term 4 feature was added.
        </p>

        <div class="stats" style="margin-bottom:14px">
            <div class="stat">
                <div class="k">{missing_term_count}</div>
                <div class="t">Reports Missing Term</div>
            </div>

            <div class="stat">
                <div class="k">{term_one_count}</div>
                <div class="t">Current Term 1 Reports</div>
            </div>

            <div class="stat">
                <div class="k">{duplicate_students_count}</div>
                <div class="t">Students With Duplicate Term 1 Reports</div>
            </div>
        </div>

        <div class="card soft" style="border-left:5px solid #1b5e20;margin-bottom:14px">
            <h2>Option 1: Mark all old reports as Term 1</h2>

            <p class="mini muted">
                This will set every report with a blank or missing term to <b>Term 1</b>.
                It will not delete anything.
            </p>

            <form method="post"
                  action="/admin/reports/term-cleanup/set-term-one"
                  onsubmit="return confirm('Set all old reports with no term to Term 1?');">
                <button class="btn success">
                    Set Missing Terms to Term 1
                </button>
            </form>
        </div>

        <div class="card soft" style="border-left:5px solid #ef4444">
            <h2>Option 2: Remove duplicate Term 1 reports</h2>

            <p class="mini muted">
                This keeps only the latest Term 1 report per student and deletes the older duplicate report records and files.
                Use this only if you are sure each student must have one Term 1 report.
            </p>

            <form method="post"
                  action="/admin/reports/term-cleanup/remove-duplicates"
                  onsubmit="return confirm('This will delete older duplicate Term 1 reports and keep only the latest one per student. Continue?');">
                <button class="btn danger">
                    Remove Duplicate Term 1 Reports
                </button>
            </form>
        </div>

        <div class="toolbar" style="margin-top:14px">
            <a class="btn secondary" href="/admin/reports">
                Back to Reports
            </a>
        </div>
    </section>
    """

    return page("Reports Term Cleanup", body)


