@app.post('/admin/reports/term-cleanup/remove-duplicates')
@require_high_admin
def admin_reports_remove_duplicate_term_one():

    r = require_admin()
    if r: return r

    conn = get_db()
    cur = conn.cursor()

    # Get students who have more than one Term 1 report
    cur.execute("""
        SELECT student_id
        FROM student_reports
        WHERE term = 'Term 1'
        GROUP BY student_id
        HAVING COUNT(*) > 1
    """)

    duplicate_students = cur.fetchall()

    deleted_count = 0
    deleted_files_count = 0

    for student in duplicate_students:
        student_id = student["student_id"]

        # Keep latest report, delete older ones
        cur.execute("""
            SELECT id, file_path
            FROM student_reports
            WHERE student_id = ?
              AND term = 'Term 1'
            ORDER BY upload_date DESC, id DESC
        """, (student_id,))

        reports = cur.fetchall()

        # First one is latest, keep it
        reports_to_delete = reports[1:]

        for report in reports_to_delete:
            file_path = report["file_path"]

            if file_path and os.path.exists(file_path):
                try:
                    os.remove(file_path)
                    deleted_files_count += 1
                except Exception:
                    pass

            cur.execute("""
                DELETE FROM student_reports
                WHERE id = ?
            """, (report["id"],))

            deleted_count += 1

    conn.commit()
    conn.close()

    return page(
        "Duplicate Reports Removed",
        f"""
        {admin_nav()}
        <div class="card">
            <h1>Duplicate Term 1 Reports Removed</h1>

            <p>
                Deleted duplicate report records: <b>{deleted_count}</b>
            </p>

            <p>
                Deleted duplicate files from storage: <b>{deleted_files_count}</b>
            </p>

            <p class="mini muted">
                The latest Term 1 report per student was kept.
            </p>

            <div class="toolbar">
                <a class="btn" href="/admin/reports">
                    Go to Reports
                </a>

                <a class="btn secondary" href="/admin/reports/term-cleanup">
                    Back to Cleanup
                </a>
            </div>
        </div>
        """
    )

@app.get('/admin/view_report/<int:rid>')
def view_report(rid):

    r = require_admin()
    if r: return r
    
    #if not is_high_admin():
    #    return page("Access Denied", "<div class='card'>Not allowed.</div>")

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT file_path FROM student_reports WHERE id=?", (rid,))
