@require_high_admin
def admin_groups_toggle_all():
    r = require_admin()
    if r:
        return r

    action = request.form.get("action")  # 'show' or 'hide'

    conn = get_db()
    cur = conn.cursor()

    if action == "show":
        cur.execute("""
            UPDATE groups
            SET is_visible = 1
            WHERE month = 'ALL'
        """)
    elif action == "hide":
        cur.execute("""
            UPDATE groups
            SET is_visible = 0
            WHERE month = 'ALL'
        """)

    conn.commit()
    conn.close()

    return redirect(url_for('admin_groups'))
    
    

