@app.post('/admin/messages/resolve-all')
@require_high_admin
def admin_messages_resolve_all():

    r = require_admin()
    if r:
        return r

    q = request.form.get("q", "").strip()

    conn = get_db()
    cur = conn.cursor()

    if q:
        cur.execute("""
            UPDATE messages
            SET resolved = 1
            WHERE resolved = 0
            AND (kind LIKE ? OR payload LIKE ?)
        """, (f"%{q}%", f"%{q}%"))
    else:
        cur.execute("""
            UPDATE messages
            SET resolved = 1
            WHERE resolved = 0
        """)

    conn.commit()
    conn.close()

    return redirect(url_for("admin_messages", q=q))




# --- Admin: Direct Messages (student/tutor DMs) ---

@app.get('/admin/direct-messages')
def admin_direct_messages():

    r = require_admin()
    if r:
        return r

    selected = request.args.get("chat")
    q = request.args.get("q", "").strip()

    conn = get_db()
    cur = conn.cursor()

    search_filter = f"%{q}%"

    # =========================
    # ONLY ADMIN CONVERSATIONS
    # =========================

    cur.execute("""
    SELECT * FROM (

        SELECT
            'student' AS role,
            s.id,
            s.full_name,
            s.grade,

            (
                SELECT body FROM direct_messages dm
                WHERE (
                    (dm.to_role='admin' AND dm.from_role='student' AND dm.from_id=s.id)
                    OR
                    (dm.from_role='admin' AND dm.to_role='student' AND dm.to_id=s.id)
                )
                ORDER BY dm.created_at DESC LIMIT 1
            ) AS last_message,

            (
                SELECT created_at FROM direct_messages dm
                WHERE (
                    (dm.to_role='admin' AND dm.from_role='student' AND dm.from_id=s.id)
                    OR
                    (dm.from_role='admin' AND dm.to_role='student' AND dm.to_id=s.id)
                )
                ORDER BY dm.created_at DESC LIMIT 1
            ) AS last_time,

            (
                SELECT COUNT(*) FROM direct_messages dm
                WHERE dm.to_role='admin'
                AND dm.from_role='student'
                AND dm.from_id=s.id
                AND dm.is_read=0
            ) AS unread

        FROM students s

        UNION ALL

        SELECT
            'tutor' AS role,
            t.id,
            t.full_name,
            NULL AS grade,

            (
                SELECT body FROM direct_messages dm
                WHERE (
                    (dm.to_role='admin' AND dm.from_role='tutor' AND dm.from_id=t.id)
                    OR
                    (dm.from_role='admin' AND dm.to_role='tutor' AND dm.to_id=t.id)
                )
                ORDER BY dm.created_at DESC LIMIT 1
            ) AS last_message,

            (
                SELECT created_at FROM direct_messages dm
                WHERE (
                    (dm.to_role='admin' AND dm.from_role='tutor' AND dm.from_id=t.id)
                    OR
                    (dm.from_role='admin' AND dm.to_role='tutor' AND dm.to_id=t.id)
                )
                ORDER BY dm.created_at DESC LIMIT 1
            ) AS last_time,

            (
                SELECT COUNT(*) FROM direct_messages dm
                WHERE dm.to_role='admin'
                AND dm.from_role='tutor'
                AND dm.from_id=t.id
                AND dm.is_read=0
            ) AS unread

        FROM tutors t

    )
    WHERE full_name LIKE ?
    AND last_time IS NOT NULL   -- 🔥 IMPORTANT FIX
    ORDER BY unread DESC, last_time DESC
    """, (search_filter,))

    conversations = cur.fetchall()

    unread_list = [c for c in conversations if c["unread"] > 0]
    read_list = [c for c in conversations if c["unread"] == 0]

    # =========================
    # SIDEBAR
    # =========================

    chat_list = """

    <div class='chat-section'>Inbox (Needs Reply)</div>
    """

    # 🔴 UNREAD FIRST
    for c in unread_list:

        role = c["role"]
        cid = c["id"]
        name = c["full_name"]

        preview = (c["last_message"] or "")[:40]
        time = format_chat_datetime(c["last_time"])

        active = "active" if selected == f"{role}|{cid}" else ""

        chat_list += f"""
        <a href="?chat={role}|{cid}"
           class="chat-user {active}"
           style="background:#fff3f3">

            <div style="display:flex;justify-content:space-between">
                <div class="chat-name"><b>🔴 {name}</b></div>
                <div class="mini">{time}</div>
            </div>

            <div class="chat-role">{preview}</div>
        </a>
        """

    # =========================
    # ALL OTHER CHATS
    # =========================

    chat_list += "<div class='chat-section'>All Conversations</div>"

    for c in read_list:

        role = c["role"]
        cid = c["id"]
        name = c["full_name"]

        preview = (c["last_message"] or "")[:40]
        time = format_chat_datetime(c["last_time"])

        active = "active" if selected == f"{role}|{cid}" else ""

        chat_list += f"""
        <a href="?chat={role}|{cid}"
           class="chat-user {active}">

            <div style="display:flex;justify-content:space-between">
                <div class="chat-name">{name}</div>
                <div class="mini">{time}</div>
            </div>

            <div class="chat-role">{preview}</div>
        </a>
        """

    # =========================
    # LOAD CHAT (FIXED)
    # =========================

    chat_messages = ""
    message_input = ""

    if selected and "|" in selected:

        role, rid = selected.split("|")
        rid = int(rid)

        # 🔥 STRICT ADMIN CONVERSATION ONLY
        cur.execute("""
        SELECT *
        FROM direct_messages
        WHERE
        (
            from_role='admin' AND to_role=? AND to_id=?
        )
        OR
        (
            to_role='admin' AND from_role=? AND from_id=?
        )
        ORDER BY created_at ASC
        """, (role, rid, role, rid))

        msgs = cur.fetchall()

        for m in msgs:

            side = "me" if m["from_role"] == "admin" else "them"
            time = format_chat_datetime(m["created_at"])

            chat_messages += f"""
            <div class="bubble {side}">
                {m['body']}
                <div class="time">{time}</div>
            </div>
            """

        # mark as read
        cur.execute("""
        UPDATE direct_messages
        SET is_read=1
        WHERE to_role='admin'
        AND from_role=?
        AND from_id=?
        """, (role, rid))
        conn.commit()

        message_input = f"""
        <form method="post" action="{url_for('admin_send_dm')}">
            <input type="hidden" name="target" value="{selected}">
            <textarea name="body" required></textarea>
            <button class="btn success">Send</button>
        </form>
        """

    conn.close()

    body = f"""
    {admin_nav()}

    <div class="card">

        <form>
            <input name="q" placeholder="Search..." value="{q}">
        </form>

        <div class="chat-layout">

            <div class="chat-list">
                {chat_list}
            </div>

            <div class="chat-window">

                <div class="chat-messages">
                    {chat_messages or "Select a conversation"}
                </div>

                <div class="chat-input">
                    {message_input}
                </div>

            </div>

        </div>

    </div>
    """

    return page("Direct Messages", body)
    


@app.post('/admin/direct-messages/send')
def admin_send_dm():

    r = require_admin()
    if r:
        return r

    target = request.form.get('target')
    body = request.form.get('body').strip()

    conn = get_db()
    cur = conn.cursor()

    now = now_utc_iso()

    # ALL tutors
    if target == "ALL_TUTORS":

        cur.execute("SELECT id FROM tutors")
        rows = cur.fetchall()

        cur.executemany("""
        INSERT INTO direct_messages
        VALUES(NULL,'admin',0,'tutor',?,NULL,?, ?,0)
        """, [(r['id'], body, now) for r in rows])

    # ALL students
    elif target == "ALL_STUDENTS":

        cur.execute("SELECT id FROM students")
        rows = cur.fetchall()

        cur.executemany("""
        INSERT INTO direct_messages
        VALUES(NULL,'admin',0,'student',?,NULL,?, ?,0)
        """, [(r['id'], body, now) for r in rows])

    # tutors by grade
    elif target.startswith("GRADE_TUTORS|"):

        grade = target.split("|")[1]

        cur.execute("""
        SELECT DISTINCT t.id
        FROM tutors t
        JOIN tutor_subjects ts ON ts.tutor_id = t.id
        JOIN subjects s ON s.id = ts.subject_id
        WHERE s.grade=?

        """, (grade,))

        rows = cur.fetchall()

        cur.executemany("""
        INSERT INTO direct_messages
        VALUES(NULL,'admin',0,'tutor',?,NULL,?, ?,0)
        """, [(r['id'], body, now) for r in rows])

    # students by grade
    elif target.startswith("GRADE_STUDENTS|"):

        grade = target.split("|")[1]

        cur.execute("""
        SELECT id FROM students
        WHERE grade=?
        """, (grade,))

        rows = cur.fetchall()

        cur.executemany("""
        INSERT INTO direct_messages
        VALUES(NULL,'admin',0,'student',?,NULL,?, ?,0)
        """, [(r['id'], body, now) for r in rows])

    # individual
    else:

        role, rid = target.split("|")

        cur.execute("""
        INSERT INTO direct_messages
        VALUES(NULL,'admin',0,?, ?,NULL,?, ?,0)
        """, (role, rid, body, now))

    conn.commit()
    conn.close()

    return redirect(url_for('admin_direct_messages'))

    
