@app.post('/student/profile/update')
def student_update_profile():

    r = require_student()
    if r:
        return r

    sid = is_student()

    full_name = request.form.get("full_name", "").strip()
    phone_whatsapp = request.form.get("phone_whatsapp", "").strip()
    guardian_name = request.form.get("guardian_name", "").strip()
    guardian_phone = request.form.get("guardian_phone", "").strip()
    email = request.form.get("email", "").strip()
    school = request.form.get("school", "").strip()
    province = request.form.get("province", "").strip()

    if not full_name or not phone_whatsapp:
        return page("Missing Information", card_msg("Full name and WhatsApp number are required."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT id
        FROM students
        WHERE phone_whatsapp=?
          AND id != ?
        LIMIT 1
    """, (phone_whatsapp, sid))

    existing = cur.fetchone()

    if existing:
        conn.close()
        return page(
            "Number Already Used",
            card_msg("This WhatsApp number is already linked to another learner profile.")
        )

    cur.execute("""
        UPDATE students
        SET full_name=?,
            phone_whatsapp=?,
            guardian_name=?,
            guardian_phone=?,
            email=?,
            school=?,
            province=?
        WHERE id=?
    """, (
        full_name,
        phone_whatsapp,
        guardian_name,
        guardian_phone,
        email,
        school,
        province,
        sid
    ))

    conn.commit()
    conn.close()

    return redirect(url_for("student_profile_page"))   
    
    
@app.post('/student/profile/pin')
def student_update_pin():

    r = require_student()
    if r:
        return r

    sid = is_student()

    current_pin = request.form.get("current_pin", "").strip()
    new_pin = request.form.get("new_pin", "").strip()
    confirm_pin = request.form.get("confirm_pin", "").strip()

    if not current_pin or not new_pin or not confirm_pin:
        return page("Missing PIN", card_msg("Please complete all PIN fields."))

    if new_pin != confirm_pin:
        return page("PIN Mismatch", card_msg("The new PIN and confirmation PIN do not match."))

    if not new_pin.isdigit() or len(new_pin) < 4 or len(new_pin) > 6:
        return page("Invalid PIN", card_msg("Your new PIN must be 4 to 6 digits."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT pin
        FROM students
        WHERE id=?
        LIMIT 1
    """, (sid,))

    student = cur.fetchone()

    if not student:
        conn.close()
        return redirect(url_for("student_login"))

    if str(student["pin"] or "") != current_pin:
        conn.close()
        return page("Incorrect PIN", card_msg("The current PIN you entered is incorrect."))

    cur.execute("""
        UPDATE students
        SET pin=?
        WHERE id=?
    """, (new_pin, sid))

    conn.commit()
    conn.close()

    return redirect(url_for("student_profile_page"))
   
    
@app.post('/student/upload-profile-picture')
def student_upload_profile_picture():
    r = require_student()
    if r: return r

    sid = is_student()

    file = request.files.get("profile_picture")

    if not file or not file.filename:
        return redirect(url_for("student_home"))

    if not is_valid_profile_picture(file.filename):
        return page("Invalid file", card_msg("Please upload a JPG, PNG, JPEG, or WEBP image."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT full_name, grade FROM students WHERE id=?", (sid,))
    student = cur.fetchone()

    if not student:
        conn.close()
        return redirect(url_for("student_home"))

    ext = os.path.splitext(file.filename.lower())[1]
    safe_student_name = secure_name(student["full_name"])
    safe_grade = secure_name(student["grade"] or "Unknown_Grade")

    grade_folder = PROFILE_PICS_DIR / safe_grade
    grade_folder.mkdir(parents=True, exist_ok=True)

    filename = f"{safe_student_name}_{sid}{ext}"
    file_path = grade_folder / filename

    file.save(file_path)

    cur.execute("""
        UPDATE students
        SET profile_picture_path=?,
            profile_picture_uploaded_at=?
        WHERE id=?
    """, (str(file_path), now_utc_iso(), sid))

    conn.commit()
    conn.close()

    return redirect(url_for("student_home"))
    

@app.get('/profile-picture/<int:sid>')
def view_profile_picture(sid):
    r = require_admin() if is_admin() else None

    # Allow students to view only their own profile picture
    if is_student() and is_student() != sid:
        return redirect(url_for("student_home"))

    if not is_student() and not is_admin() and not session.get("aqm_id"):
        return redirect(url_for("student_login"))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT profile_picture_path FROM students WHERE id=?", (sid,))
    row = cur.fetchone()
    conn.close()

    if not row or not row["profile_picture_path"] or not os.path.exists(row["profile_picture_path"]):
        return page("Not found", card_msg("Profile picture not found."))

    return send_from_directory(
        os.path.dirname(row["profile_picture_path"]),
        os.path.basename(row["profile_picture_path"])
    )


@app.get('/aqm/download-profile-pictures-zip')
def aqm_download_profile_pictures_zip():
    r = require_aqm()
    if r: return r

    grade_filter = request.args.get("grade", "").strip()

    conn = get_db()
    cur = conn.cursor()

    params = []
    grade_sql = ""

    if grade_filter:
        grade_sql = "WHERE grade = ?"
        params.append(grade_filter)

    cur.execute(f"""
        SELECT id, full_name, grade, profile_picture_path
        FROM students
        {grade_sql}
        ORDER BY grade, full_name
    """, params)

    students = cur.fetchall()
    conn.close()

    memory_file = io.BytesIO()
    added = 0

    with zipfile.ZipFile(memory_file, "w", zipfile.ZIP_DEFLATED) as zf:
        for st in students:
            path = st["profile_picture_path"]

            if not path or not os.path.exists(path):
                continue

            ext = os.path.splitext(path)[1].lower()
            learner_name = secure_name(st["full_name"])
            grade_name = secure_name(grade_label(st["grade"] or "Unknown_Grade"))

            zip_name = f"{grade_name}/{learner_name}{ext}"
            zf.write(path, zip_name)
            added += 1

    if added == 0:
        return page("No profile pictures", card_msg("No profile pictures found for the selected filter."))

    memory_file.seek(0)

    response = make_response(memory_file.read())
    response.headers["Content-Type"] = "application/zip"

    if grade_filter:
        filename = f"EBTA_Profile_Pictures_{secure_name(grade_label(grade_filter))}.zip"
    else:
        filename = "EBTA_All_Profile_Pictures.zip"

    response.headers["Content-Disposition"] = f"attachment; filename={filename}"

    return response


@app.get('/download-profile-picture/<int:sid>')
def download_profile_picture(sid):
    if not (is_admin() or is_student() or session.get("aqm_id")):
        return redirect(url_for("student_login"))

    if is_student() and is_student() != sid:
        return redirect(url_for("student_home"))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT full_name, profile_picture_path
        FROM students
        WHERE id=?
    """, (sid,))

    row = cur.fetchone()
    conn.close()

    if not row or not row["profile_picture_path"] or not os.path.exists(row["profile_picture_path"]):
        return page("Not found", card_msg("Profile picture not found."))

    ext = os.path.splitext(row["profile_picture_path"])[1].lower()
    download_name = f"{secure_name(row['full_name'])}{ext}"

    return send_from_directory(
        os.path.dirname(row["profile_picture_path"]),
        os.path.basename(row["profile_picture_path"]),
        as_attachment=True,
        download_name=download_name
    )



