    cur.execute("""
        INSERT INTO social_media_weekly_reports(
            manager_id,
            week_start,
            week_end,
            posts_published,
            stories_posted,
            platforms_used,
            comments_received,
            dms_received,
            dms_responded,
            comments_responded,
            best_post_link,
            best_post_engagement,
            challenges,
            next_week_plan,
            status,
            created_at,
            updated_at
        )
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    """, (
        mid,
        week_start,
        week_end,
        posts_published,
        stories_posted,
        platforms_used,
        comments_received,
        dms_received,
        dms_responded,
        comments_responded,
        best_post_link,
        best_post_engagement,
        challenges,
        next_week_plan,
        status,
        now,
        now
    ))

    conn.commit()
    conn.close()

    return redirect(url_for("social_media_weekly_reports"))
    
    
