@app.get('/admission/students')
def admission_students():

    r = require_admission_coordinator()
    if r:
        return r

    q = request.args.get("q", "").strip()
    grade = request.args.get("grade", "").strip()

    # Important:
    # Leave month empty by default so the page shows ALL students.
    # Only filter by month when the Admission Coordinator selects a month.
    month = request.args.get("month", "").strip()

    try:
        page_num = int(request.args.get("page", 1))
    except:
        page_num = 1

    if page_num < 1:
        page_num = 1

    limit = 20
    offset = (page_num - 1) * limit

    conn = get_db()
    cur = conn.cursor()

    where = []
    params = []

    # ================= MONTH FILTER =================
    if month:
        where.append("""
            EXISTS (
                SELECT 1
                FROM enrollments e
                WHERE e.student_id = s.id
                  AND e.month = ?
            )
        """)
        params.append(month)

    # ================= SEARCH FILTER =================
    if q:
        search = f"%{q}%"

        where.append("""
            (
                s.full_name LIKE ?
                OR s.phone_whatsapp LIKE ?
                OR s.guardian_phone LIKE ?
                OR IFNULL(s.guardian_name, '') LIKE ?
                OR IFNULL(s.email, '') LIKE ?
                OR IFNULL(s.school, '') LIKE ?
                OR IFNULL(s.province, '') LIKE ?
                OR s.grade LIKE ?
                OR EXISTS (
                    SELECT 1
                    FROM enrollments e2
                    JOIN subjects sub2 ON sub2.id = e2.subject_id
                    WHERE e2.student_id = s.id
                      AND (
                            sub2.name LIKE ?
                            OR sub2.grade LIKE ?
                            OR e2.status LIKE ?
                            OR e2.month LIKE ?
                      )
                )
            )
        """)

        params += [
            search, search, search, search,
            search, search, search, search,
            search, search, search, search
        ]

    if grade:
        where.append("s.grade = ?")
        params.append(grade)

    where_sql = "WHERE " + " AND ".join(where) if where else ""

    # ================= COUNT =================
    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM students s
        {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + limit - 1) // limit)

    if page_num > total_pages:
        page_num = total_pages
        offset = (page_num - 1) * limit

    # ================= SUBJECT / STATUS SUBQUERIES =================
    # If month is selected, show subjects/statuses for that month only.
    # If no month is selected, show all known enrolled subjects/statuses.
    if month:
        subjects_sql = """
            (
                SELECT GROUP_CONCAT(DISTINCT sub.name)
                FROM enrollments e3
                JOIN subjects sub ON sub.id = e3.subject_id
                WHERE e3.student_id = s.id
                  AND e3.month = ?
            ) AS enrolled_subjects
        """

        statuses_sql = """
            (
                SELECT GROUP_CONCAT(DISTINCT e4.status)
                FROM enrollments e4
                WHERE e4.student_id = s.id
                  AND e4.month = ?
            ) AS enrollment_statuses
        """

        select_params = [month, month]

    else:
        subjects_sql = """
            (
                SELECT GROUP_CONCAT(DISTINCT sub.name)
                FROM enrollments e3
                JOIN subjects sub ON sub.id = e3.subject_id
                WHERE e3.student_id = s.id
            ) AS enrolled_subjects
        """

        statuses_sql = """
            (
                SELECT GROUP_CONCAT(DISTINCT e4.status)
                FROM enrollments e4
                WHERE e4.student_id = s.id
            ) AS enrollment_statuses
        """

        select_params = []

    data_params = list(select_params)
    data_params.extend(params)
    data_params.extend([limit, offset])

    # ================= MAIN DATA =================
    cur.execute(f"""
        SELECT
            s.*,
            {subjects_sql},
            {statuses_sql}
        FROM students s
        {where_sql}
        ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER), s.full_name
        LIMIT ? OFFSET ?
    """, data_params)

    rows = cur.fetchall()
    conn.close()

    trs = ""

    for s in rows:
        subject_label = "Subjects This Month" if month else "All Enrolled Subjects"

        trs += f"""
        <tr>
            <td>
                <strong>{escape(s['full_name'])}</strong>
                <div class="mini muted">PIN: {escape(s['pin'] or '—')}</div>
            </td>

            <td>{grade_label(s['grade'])}</td>

            <td>{escape(s['phone_whatsapp'] or '—')}</td>

            <td>
                {escape(s['guardian_name'] or '—')}
                <div class="mini muted">{escape(s['guardian_phone'] or '—')}</div>
            </td>

            <td>{escape(s['email'] or '—')}</td>

            <td>
                {escape(s['school'] or '—')}
                <div class="mini muted">{escape(s['province'] or '—')}</div>
            </td>

            <td>
                {escape(s['enrolled_subjects'] or '—')}
                <div class="mini muted">
                    Status: {escape(s['enrollment_statuses'] or '—')}
                </div>
            </td>

            <td>{escape((s['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    if month:
        showing_label = f"Showing students enrolled for: <b>{pretty_month_label(month)}</b>"
        subject_heading = "Subjects This Month"
    else:
        showing_label = "Showing <b>all students</b>. Select a month only if you want to filter by enrollment month."
        subject_heading = "All Enrolled Subjects"

    body = f"""
    {admission_nav()}

    <section class="card">
        <h1>Students</h1>

        <p class="muted">
            View learner details captured on the portal. By default, this page shows all students.
            Use the month filter only when you want to view students enrolled in a specific month.
        </p>

        <form method="get" class="toolbar">

            <input type="month"
                   name="month"
                   value="{escape(month)}"
                   title="Filter students by enrollment month">

            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search name, phone, guardian, email, school, province, subject, status or month">

            <select name="grade">
                <option value="">All Grades</option>
                {''.join(
                    f"<option value='{g}' {'selected' if grade==g else ''}>{grade_label(g)}</option>"
                    for g in ["G8","G9","G10","G11","G12","G13"]
                )}
            </select>

            <button class="btn mini">Search</button>

            <a class="btn mini secondary" href="{url_for('admission_students')}">
                Clear
            </a>
        </form>
        
        <div class="mini muted" style="margin:10px 0">
            {showing_label}
        </div>

        <div class="mini muted" style="margin-bottom:10px">
            Showing {len(rows)} of {total} student record(s).
        </div>

        {pagination_controls("/admission/students", page_num, total_pages, {"month": month, "q": q, "grade": grade})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Student</th>
                        <th>Grade</th>
                        <th>Phone</th>
                        <th>Guardian</th>
                        <th>Email</th>
                        <th>School / Province</th>
                        <th>{subject_heading}</th>
                        <th>Created</th>
                    </tr>
                </thead>

                <tbody>
                    {trs or "<tr><td colspan='8'>No students found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/admission/students", page_num, total_pages, {"month": month, "q": q, "grade": grade})}
    </section>
    """

    return page("Admission Students", body)
    
    
@app.get('/admission/groups')
def admission_groups():

    r = require_admission_coordinator()
    if r:
        return r

    month = get_admin_active_month()

    page_num = max(1, int(request.args.get("page", 1)))
    limit = 15
    offset = (page_num - 1) * limit

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM groups g
        JOIN subjects sub ON sub.id = g.subject_id
        WHERE (g.month = ? OR UPPER(g.month) = 'ALL')
          AND g.is_visible = 1
    """, (month,))

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + limit - 1) // limit)

    cur.execute("""
        SELECT
            g.*,
            sub.name AS subject_name,
            sub.grade AS subject_grade
        FROM groups g
        JOIN subjects sub ON sub.id = g.subject_id
        WHERE (g.month = ? OR UPPER(g.month) = 'ALL')
          AND g.is_visible = 1
        ORDER BY
            CASE WHEN UPPER(g.month) = 'ALL' THEN 0 ELSE 1 END,
            CAST(REPLACE(sub.grade,'G','') AS INTEGER),
            sub.name
        LIMIT ? OFFSET ?
    """, (month, limit, offset))

    rows = cur.fetchall()
    conn.close()

    trs = ""

    for g in rows:
        visible = "Visible" if g["is_visible"] == 1 else "Hidden"

        if str(g["month"]).upper() == "ALL":
            group_type = "Permanent"
        else:
            group_type = pretty_month_label(g["month"])

        invite = "—"

        if g["invite_link"]:
            invite = f"<a target='_blank' href='{escape(g['invite_link'])}'>Open Group</a>"

        trs += f"""
        <tr>
            <td>{grade_label(g['subject_grade'])}</td>
            <td>{escape(g['subject_name'])}</td>
            <td>{escape(group_type)}</td>
            <td>{invite}</td>
            <td><span class="chip">{visible}</span></td>
            <td>{escape((g['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    body = f"""
    {admission_nav()}

    <section class="card">
        <h1>Group Links</h1>

        <p class="muted">
            View visible EBTA group links. Creating, editing and deleting groups are restricted.
        </p>

        {pagination_controls("/admission/groups", page_num, total_pages)}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Group Type / Month</th>
                        <th>Group Link</th>
                        <th>Visibility</th>
                        <th>Created</th>
                    </tr>
                </thead>

                <tbody>
                    {trs or "<tr><td colspan='6'>No visible group links found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/admission/groups", page_num, total_pages)}
    </section>
    """

    return page("Admission Groups", body)
    

