@app.post('/admin/discounts-control/mark-old-sms-sent')
@require_high_admin
def admin_mark_old_discount_sms_sent():

    r = require_admin()
    if r:
        return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can update old discount SMS records."))

    conn = get_db()
    cur = conn.cursor()

    now = now_utc_iso()

    cur.execute("""
        UPDATE discount_coupons
        SET sms_sent=1,
            sms_sent_at=COALESCE(sms_sent_at, ?),
            sms_sent_by_role='admin_backfill',
            sms_sent_by_id=NULL,
            sms_last_error=NULL
        WHERE source='MANUAL'
          AND target_student_id IS NOT NULL
          AND COALESCE(sms_sent, 0) = 0
    """, (now,))

    updated = cur.rowcount or 0

    conn.commit()
    conn.close()

    return page(
        "Old Discount SMS Status Updated",
        f"""
        {admin_nav()}

        <section class="card">
            <h1>Old Discount SMS Status Updated</h1>

            <div class="card soft" style="border-left:5px solid #1b5e20">
                <p>
                    <b>{updated}</b> old Admission Coordinator discount code(s) were marked as SMS Sent.
                </p>

                <p class="muted">
                    These codes will now show as SMS Sent on the Admission Coordinator discount page.
                </p>
            </div>

            <a class="btn" href="{url_for('admin_discounts_control')}">
                Back to Discount Control
            </a>
        </section>
        """
    )


@app.post('/admin/discounts-control/toggle')
@require_high_admin
def admin_discounts_toggle():

    r = require_admin()
    if r:
        return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can update discount settings."))

    current = get_setting("discounts_locked", "1")
    new_value = "0" if current == "1" else "1"

    set_setting("discounts_locked", new_value)

    return redirect(url_for("admin_discounts_control"))


@app.post('/admin/discounts-control/delete-toggle')
@require_high_admin
def admin_discounts_delete_toggle():

    r = require_admin()
    if r:
        return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can update discount delete settings."))

    current = get_setting("discounts_delete_locked", "1")
    new_value = "0" if current == "1" else "1"

    set_setting("discounts_delete_locked", new_value)

    return redirect(url_for("admin_discounts_control"))


@app.get('/admission/discounts')
def admission_discounts():

    r = require_admission_coordinator()
    if r:
        return r

    q = request.args.get("q", "").strip()
    grade_filter = request.args.get("grade", "").strip()
    locked = get_setting("discounts_locked", "1")
    delete_locked = get_setting("discounts_delete_locked", "1")

    try:
        students_page = int(request.args.get("students_page", 1))
    except:
        students_page = 1

    try:
        coupons_page = int(request.args.get("coupons_page", 1))
    except:
        coupons_page = 1

    if students_page < 1:
        students_page = 1

    if coupons_page < 1:
        coupons_page = 1

    students_per_page = 10
    coupons_per_page = 10

    students_offset = (students_page - 1) * students_per_page
    coupons_offset = (coupons_page - 1) * coupons_per_page

    conn = get_db()
    cur = conn.cursor()

    ensure_all_student_referral_codes(conn)
    conn.commit()

    # ================= STUDENT SEARCH + GRADE FILTER =================
    where = []
    params = []

    if q:
        search = f"%{q}%"

        where.append("""
            (
                s.full_name LIKE ?
                OR s.phone_whatsapp LIKE ?
                OR s.guardian_phone LIKE ?
                OR IFNULL(s.guardian_name, '') LIKE ?
                OR IFNULL(s.email, '') LIKE ?
                OR IFNULL(s.school, '') LIKE ?
                OR IFNULL(s.province, '') LIKE ?
                OR s.grade LIKE ?
                OR s.referral_code LIKE ?
                OR EXISTS (
                    SELECT 1
                    FROM enrollments e
                    JOIN subjects sub ON sub.id = e.subject_id
                    WHERE e.student_id = s.id
                      AND (
                            sub.name LIKE ?
                            OR sub.grade LIKE ?
                            OR REPLACE(sub.grade, 'G', 'Grade ') LIKE ?
                      )
                )
            )
        """)

        params += [
            search, search, search, search, search, search,
            search, search, search, search, search, search
        ]

    if grade_filter:
        where.append("s.grade = ?")
        params.append(grade_filter)

    where_sql = "WHERE " + " AND ".join(where) if where else ""

    # ================= STUDENT COUNT =================
    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM students s
        {where_sql}
    """, params)

    total_students = cur.fetchone()["c"] or 0
    total_student_pages = max(1, (total_students + students_per_page - 1) // students_per_page)

    if students_page > total_student_pages:
        students_page = total_student_pages
        students_offset = (students_page - 1) * students_per_page

    # ================= DISPLAY STUDENTS =================
    student_params = list(params)
    student_params.extend([students_per_page, students_offset])

    cur.execute(f"""
        SELECT
            s.id,
            s.full_name,
            s.phone_whatsapp,
            s.grade,
            s.referral_code,
            COALESCE(s.referral_points,0) AS referral_points,
            COALESCE(s.referral_total_count,0) AS referral_total_count
        FROM students s
        {where_sql}
        ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER), s.full_name
        LIMIT ? OFFSET ?
    """, student_params)

    students = cur.fetchall()

    # ================= STUDENTS FOR CREATE FORM =================
    # This is separate from the paginated table so the dropdown still has enough students.
    cur.execute("""
        SELECT
            id,
            full_name,
            phone_whatsapp,
            grade
        FROM students
        ORDER BY CAST(REPLACE(grade,'G','') AS INTEGER), full_name
        LIMIT 2000
    """)

    form_students = cur.fetchall()

    # ================= SUBJECTS FOR CREATE FORM =================
    cur.execute("""
        SELECT id, name, grade
        FROM subjects
        ORDER BY CAST(REPLACE(grade,'G','') AS INTEGER), name
    """)

    subjects = cur.fetchall()

    # ================= COUPON SEARCH + GRADE FILTER =================
    coupon_where = []
    coupon_params = []

    if q:
        search = f"%{q}%"

        coupon_where.append("""
            (
                dc.code LIKE ?
                OR dc.source LIKE ?
                OR dc.status LIKE ?
                OR dc.applies_to LIKE ?
                OR CAST(dc.discount_percent AS TEXT) LIKE ?

                OR s.full_name LIKE ?
                OR owner.full_name LIKE ?

                OR s.phone_whatsapp LIKE ?
                OR owner.phone_whatsapp LIKE ?

                OR IFNULL(s.guardian_phone, '') LIKE ?
                OR IFNULL(owner.guardian_phone, '') LIKE ?

                OR IFNULL(s.email, '') LIKE ?
                OR IFNULL(owner.email, '') LIKE ?

                OR IFNULL(s.school, '') LIKE ?
                OR IFNULL(owner.school, '') LIKE ?

                OR IFNULL(s.province, '') LIKE ?
                OR IFNULL(owner.province, '') LIKE ?

                OR s.grade LIKE ?
                OR owner.grade LIKE ?

                OR s.referral_code LIKE ?
                OR owner.referral_code LIKE ?

                OR sub.name LIKE ?
                OR sub.grade LIKE ?
                OR REPLACE(sub.grade, 'G', 'Grade ') LIKE ?
            )
        """)

        coupon_params += [
            search, search, search, search, search,
            search, search,
            search, search,
            search, search,
            search, search,
            search, search,
            search, search,
            search, search,
            search, search,
            search, search, search
        ]

    if grade_filter:
        coupon_where.append("""
            (
                s.grade = ?
                OR owner.grade = ?
                OR sub.grade = ?
            )
        """)
        coupon_params += [grade_filter, grade_filter, grade_filter]

    coupon_where_sql = "WHERE " + " AND ".join(coupon_where) if coupon_where else ""

    # ================= COUPON COUNT =================
    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM discount_coupons dc
        LEFT JOIN students s ON s.id = dc.target_student_id
        LEFT JOIN students owner ON owner.id = dc.owner_student_id
        LEFT JOIN subjects sub ON sub.id = dc.subject_id
        {coupon_where_sql}
    """, coupon_params)

    total_coupons = cur.fetchone()["c"] or 0
    total_coupon_pages = max(1, (total_coupons + coupons_per_page - 1) // coupons_per_page)

    if coupons_page > total_coupon_pages:
        coupons_page = total_coupon_pages
        coupons_offset = (coupons_page - 1) * coupons_per_page

    # ================= DISPLAY COUPONS =================
    coupon_data_params = list(coupon_params)
    coupon_data_params.extend([coupons_per_page, coupons_offset])

    cur.execute(f"""
        SELECT
            dc.*,
            s.full_name AS target_name,
            owner.full_name AS owner_name,
            sub.name AS subject_name,
            sub.grade AS subject_grade
        FROM discount_coupons dc
        LEFT JOIN students s ON s.id = dc.target_student_id
        LEFT JOIN students owner ON owner.id = dc.owner_student_id
        LEFT JOIN subjects sub ON sub.id = dc.subject_id
        {coupon_where_sql}
        ORDER BY dc.created_at DESC
        LIMIT ? OFFSET ?
    """, coupon_data_params)

    coupons = cur.fetchall()
    conn.close()

    student_options = "".join(
        f"""
        <option value="{escape(s['full_name'])} - {grade_label(s['grade'])} - {escape(s['phone_whatsapp'] or '')}"
                data-id="{s['id']}">
        </option>
        """
        for s in form_students
    )

    subject_options = """
    <option value="">All selected subjects</option>
    """ + "".join(
        f"""
        <option value="{sub['id']}">
            {grade_label(sub['grade'])} - {escape(sub['name'])}
        </option>
        """
        for sub in subjects
    )

    create_form = ""

    if locked == "1":
        create_form = """
        <div class="card soft" style="border-left:5px solid #ef4444">
            <h2>Discount Creation Locked</h2>
            <p class="muted">
                High admin has locked discount creation. You can view existing codes and referral information only.
            </p>
        </div>
        """
    else:
        create_form = f"""
        <div class="card soft" style="border-left:5px solid #1b5e20;margin-bottom:14px">
            <h2>Create Student Discount Code</h2>

            <form method="post"
                  action="{url_for('admission_discount_create')}"
                  class="grid"
                  style="grid-template-columns:1fr 1fr 1fr;gap:10px">

                <div>
                    <label>Student</label>

                    <input list="student_discount_list"
                           id="student_discount_search"
                           placeholder="Type learner name, surname, grade or phone"
                           required>

                    <input type="hidden"
                           name="student_id"
                           id="student_discount_id">

                    <datalist id="student_discount_list">
                        {student_options}
                    </datalist>

                    <div class="mini muted">
                        Start typing to find the learner, then select the correct option.
                    </div>
                </div>

                <div>
                    <label>Discount</label>
                    <select name="discount_percent" required>
                        <option value="50">50% Discount</option>
                        <option value="100">100% Discount</option>
                    </select>
                </div>

                <div>
                    <label>Applies To</label>
                    <select name="subject_id">
                        {subject_options}
                    </select>
                    <div class="mini muted">
                        Leave blank if discount applies to all selected subjects.
                    </div>
                </div>

                <div style="grid-column:1/-1">
                    <label>Notes Optional</label>
                    <input name="notes" placeholder="Reason for discount or approval note">
                </div>

                <div style="grid-column:1/-1">
                    <button class="btn success">
                        Generate Discount Code
                    </button>
                </div>

            </form>
        </div>
        """

    student_rows = ""

    for s in students:
        student_rows += f"""
        <tr>
            <td>
                <strong>{escape(s['full_name'])}</strong>
                <div class="mini muted">{grade_label(s['grade'])}</div>
            </td>

            <td>{escape(s['phone_whatsapp'] or '—')}</td>

            <td>
                <span class="chip">{escape(s['referral_code'] or '—')}</span>
            </td>

            <td>{s['referral_points']} / 5</td>

            <td>{s['referral_total_count']}</td>
        </tr>
        """

    coupon_rows = ""

    for c in coupons:

        if c["applies_to"] == "SUBJECT" and c["subject_name"]:
            applies_to = f"{grade_label(c['subject_grade'])} {escape(c['subject_name'])}"
        elif c["applies_to"] == "ANY_SUBJECT":
            applies_to = "Any one selected subject"
        else:
            applies_to = "All selected subjects"

        status_class = "active" if c["status"] == "ACTIVE" else "lapsed"
        
        sms_status_html = ""

        if int(c["sms_sent"] or 0) == 1:
            sms_status_html = f"""
            <span class="chip active">SMS Sent</span>
            <div class="mini muted">
                {escape((c["sms_sent_at"] or "")[:16].replace("T", " "))}
            </div>
            """
        else:
            sms_status_html = """
            <span class="chip lapsed">SMS Not Sent</span>
            """

            if c["sms_last_error"]:
                sms_status_html += f"""
                <div class="mini muted" style="color:#b91c1c">
                    Last error: {escape(c["sms_last_error"])}
                </div>
                """

        sms_button = ""

        if c["target_student_id"] and c["status"] == "ACTIVE":

            if int(c["sms_sent"] or 0) == 1:
                sms_button = """
                <span class="mini muted">
                    SMS already sent
                </span>
                """
            else:
                sms_button = f"""
                <form method="post"
                      action="{url_for('admission_discount_sms', coupon_id=c['id'])}"
                      style="display:inline"
                      onsubmit="return confirm('Send this discount code by SMS?');">
                    <button class="btn mini secondary">Send SMS</button>
                </form>
                """
            
        delete_button = ""

        if delete_locked == "0":
            delete_button = f"""
            <form method="post"
                  action="{url_for('admission_discount_delete', coupon_id=c['id'])}"
                  style="display:inline"
                  onsubmit="return confirm('Delete this discount code? This cannot be undone.');">
                <button class="btn mini danger">
                    Delete
                </button>
            </form>
            """
        else:
            delete_button = """
            <span class="mini muted">
                Delete locked
            </span>
            """

        coupon_rows += f"""
        <tr>
            <td>
                <span class="chip">{escape(c['code'])}</span>
            </td>

            <td>{escape(c['target_name'] or c['owner_name'] or '—')}</td>

            <td>{c['discount_percent']}%</td>

            <td>{applies_to}</td>

            <td>{escape(c['source'])}</td>

            <td>
                <span class="chip {status_class}">
                    {escape(c['status'])}
                </span>
            </td>

            <td>{c['used_count']} / {c['max_uses']}</td>

            <td>{sms_status_html}</td>

            <td>
                <div style="display:flex;gap:6px;flex-wrap:wrap">
                    {sms_button}
                    {delete_button}
                </div>
            </td>
        </tr>
        """

    def admission_discounts_pagination(which, current_page, total_pages):
        if total_pages <= 1:
            return ""

        links = []

        def make_link(label, target_page):
            params = {
                "q": q,
                "grade": grade_filter,
                "students_page": students_page,
                "coupons_page": coupons_page
            }

            if which == "students":
                params["students_page"] = target_page
            else:
                params["coupons_page"] = target_page

            clean_params = {
                k: v for k, v in params.items()
                if v not in [None, ""]
            }

            return f"""
            <a class="btn mini secondary"
               href="{url_for('admission_discounts')}?{urlencode(clean_params)}">
                {label}
            </a>
            """

        if current_page > 1:
            links.append(make_link("First", 1))
            links.append(make_link("Prev", current_page - 1))

        links.append(f"""
        <span class="chip">
            Page {current_page} / {total_pages}
        </span>
        """)

        if current_page < total_pages:
            links.append(make_link("Next", current_page + 1))
            links.append(make_link("Last", total_pages))

        return f"""
        <div class="toolbar" style="justify-content:center;margin:12px 0;gap:6px;flex-wrap:wrap">
            {''.join(links)}
        </div>
        """

    students_pagination = admission_discounts_pagination(
        "students",
        students_page,
        total_student_pages
    )

    coupons_pagination = admission_discounts_pagination(
        "coupons",
        coupons_page,
        total_coupon_pages
    )

    grade_options = "".join(
        f"""
        <option value="{g}" {'selected' if grade_filter == g else ''}>
            {grade_label(g)}
        </option>
        """
        for g in ["G8", "G9", "G10", "G11", "G12", "G13"]
    )

    body = f"""
    {admission_nav()}

    <section class="card">
        <h1>Discount Codes</h1>

        <p class="muted">
            Manage manually generated student discount codes and referral reward discount codes.
        </p>
        
        <div class="mini muted" style="margin-bottom:10px">
            Delete access:
            {"Unlocked" if delete_locked == "0" else "Locked by High Admin"}
        </div>
        
        <div class="toolbar" style="margin-bottom:12px">
            <form method="post"
                  action="{url_for('admission_discount_sms_all')}"
                  onsubmit="return confirm('Send SMS to all active, unused discount codes that have not been sent yet?');">
                <button class="btn success">
                    Send SMS to All Unsent Discount Codes
                </button>
            </form>
        </div>

        {create_form}

        <form method="get" class="toolbar">
            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search name, surname, phone, school, subject, grade, referral code, coupon code or status">

            <select name="grade">
                <option value="">All Grades</option>
                {grade_options}
            </select>

            <button class="btn mini">Search</button>

            <a class="btn mini secondary" href="{url_for('admission_discounts')}">
                Clear
            </a>
            
            <a class="btn mini secondary" href="{url_for('admission_referrals')}">
                View Referral Codes
            </a>
            
        </form>

        <div class="card soft" style="margin-top:14px">
            <h2>Discount Codes</h2>

            <div class="mini muted" style="margin-bottom:8px">
                Showing {len(coupons)} of {total_coupons} discount code record(s).
            </div>

            {coupons_pagination}

            <div class="scroll-x">
                <table>
                    <thead>
                        <tr>
                            <th>Code</th>
                            <th>Student</th>
                            <th>Discount</th>
                            <th>Applies To</th>
                            <th>Source</th>
                            <th>Status</th>
                            <th>Usage</th>
                            <th>SMS Status</th>
                            <th>Actions</th>
                        </tr>
                    </thead>

                    <tbody>
                        {coupon_rows or "<tr><td colspan='9'>No discount codes found.</td></tr>"}
                    </tbody>
                </table>
            </div>

            {coupons_pagination}
        </div>
        
        <script>
            document.addEventListener("DOMContentLoaded", function () {{
                const searchInput = document.getElementById("student_discount_search");
                const hiddenInput = document.getElementById("student_discount_id");
                const options = document.querySelectorAll("#student_discount_list option");

                if (!searchInput || !hiddenInput) {{
                    return;
                }}

                searchInput.addEventListener("input", function () {{
                    hiddenInput.value = "";

                    options.forEach(function (option) {{
                        if (option.value === searchInput.value) {{
                            hiddenInput.value = option.dataset.id || "";
                        }}
                    }});
                }});

                const form = searchInput.closest("form");

                if (form) {{
                    form.addEventListener("submit", function (event) {{
                        if (!hiddenInput.value) {{
                            event.preventDefault();
                            alert("Please select a learner from the search list before generating a discount code.");
                            searchInput.focus();
                        }}
                    }});
                }}
            }});
        </script>
        
    </section>
    """

    return page("Admission Discounts", body)
    
    
@app.post('/admission/discounts/create')
def admission_discount_create():

    r = require_admission_coordinator()
    if r:
        return r

    if get_setting("discounts_locked", "1") == "1":
        return page("Locked", card_msg("Discount creation is currently locked by high admin."))

    student_id = request.form.get("student_id")
    discount_percent = request.form.get("discount_percent")
    subject_id = request.form.get("subject_id", "").strip()
    notes = request.form.get("notes", "").strip()

    try:
        discount_percent = int(discount_percent)
    except:
        return page("Invalid", card_msg("Invalid discount percentage."))

    if discount_percent not in [50, 100]:
        return page("Invalid", card_msg("Discount must be 50% or 100%."))

    applies_to = "SUBJECT" if subject_id else "ALL"
    subject_id_value = int(subject_id) if subject_id else None

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT id FROM students WHERE id=?", (student_id,))
    student = cur.fetchone()

    if not student:
        conn.close()
        return page("Invalid", card_msg("Student not found."))

    while True:
        code = generate_short_code(f"D{discount_percent}", 6)

        cur.execute("SELECT id FROM discount_coupons WHERE code=?", (code,))

        if not cur.fetchone():
            break

    cur.execute("""
        INSERT INTO discount_coupons(
            code,
            target_student_id,
            owner_student_id,
            discount_percent,
            applies_to,
            subject_id,
            source,
            status,
            max_uses,
            used_count,
            created_by_role,
            created_by_id,
            created_at,
            notes
        )
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    """, (
        code,
        student_id,
        None,
        discount_percent,
        applies_to,
        subject_id_value,
        "MANUAL",
        "ACTIVE",
        1,
        0,
        "admission",
        session.get("admission_coordinator_id"),
        now_utc_iso(),
        notes
    ))

    conn.commit()
    conn.close()

    return page(
        "Discount Code Created",
        f"""
        {admission_nav()}

        <section class="card">
            <h1>Discount Code Created</h1>

            <p>
                <b>Code:</b>
                <span class="chip" style="font-size:20px;padding:10px 14px;letter-spacing:1px">
                    {escape(code)}
                </span>
            </p>

            <p class="muted">
                Share this code privately with the learner. They can use it during enrollment.
            </p>

            <a class="btn" href="{url_for('admission_discounts')}">Back to Discounts</a>
        </section>
        """
    )
    
    
@app.post('/admission/discounts/<int:coupon_id>/sms')
def admission_discount_sms(coupon_id):

    r = require_admission_coordinator()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            dc.id,
            dc.code,
            dc.discount_percent,
            dc.applies_to,
            dc.sms_sent,
            s.full_name,
            s.phone_whatsapp
        FROM discount_coupons dc
        JOIN students s ON s.id = dc.target_student_id
        WHERE dc.id=?
          AND dc.status='ACTIVE'
        LIMIT 1
    """, (coupon_id,))

    row = cur.fetchone()

    if not row:
        conn.close()
        return page("Not found", card_msg("Active discount code not found."))
        
    if int(row["sms_sent"] or 0) == 1:
        conn.close()
        return page(
            "SMS Already Sent",
            card_msg("This discount code SMS was already sent, so it cannot be sent again from the Admission Coordinator portal.")
        )

    sms_body = build_discount_sms_body(
        row["full_name"],
        row["discount_percent"],
        row["code"],
        row["applies_to"]
    )

    try:
        send_sms_notification(row["phone_whatsapp"], sms_body)

        cur.execute("""
            UPDATE discount_coupons
            SET sms_sent=1,
                sms_sent_at=?,
                sms_sent_by_role='admission',
                sms_sent_by_id=?,
                sms_last_error=NULL
            WHERE id=?
        """, (
            now_utc_iso(),
            session.get("admission_coordinator_id"),
            coupon_id
        ))

        conn.commit()
        conn.close()

    except Exception as e:
        print("Discount SMS error:", e)

        cur.execute("""
            UPDATE discount_coupons
            SET sms_last_error=?
            WHERE id=?
        """, (str(e)[:300], coupon_id))

        conn.commit()
        conn.close()

        return page("SMS Error", card_msg("Could not send SMS. Please check SMS setup."))

    return redirect(request.referrer or url_for("admission_discounts"))


@app.post('/admission/discounts/sms-all')
def admission_discount_sms_all():

    r = require_admission_coordinator()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            dc.id,
            dc.code,
            dc.discount_percent,
            dc.applies_to,
            s.full_name,
            s.phone_whatsapp
        FROM discount_coupons dc
        JOIN students s ON s.id = dc.target_student_id
        WHERE dc.status='ACTIVE'
          AND dc.used_count < dc.max_uses
          AND COALESCE(dc.sms_sent, 0) = 0
          AND s.phone_whatsapp IS NOT NULL
          AND TRIM(s.phone_whatsapp) != ''
        ORDER BY dc.created_at DESC
    """)

    rows = cur.fetchall()

    sent_count = 0
    failed_count = 0

    for row in rows:
        sms_body = build_discount_sms_body(
            row["full_name"],
            row["discount_percent"],
            row["code"],
            row["applies_to"]
        )

        try:
            send_sms_notification(row["phone_whatsapp"], sms_body)

            cur.execute("""
                UPDATE discount_coupons
                SET sms_sent=1,
                    sms_sent_at=?,
                    sms_sent_by_role='admission',
                    sms_sent_by_id=?,
                    sms_last_error=NULL
                WHERE id=?
            """, (
                now_utc_iso(),
                session.get("admission_coordinator_id"),
                row["id"]
            ))

            sent_count += 1

        except Exception as e:
            print("Bulk discount SMS error:", e)

            cur.execute("""
                UPDATE discount_coupons
                SET sms_last_error=?
                WHERE id=?
            """, (
                str(e)[:300],
                row["id"]
            ))

            failed_count += 1

    conn.commit()
    conn.close()

    return page(
        "Bulk Discount SMS Complete",
        f"""
        {admission_nav()}

        <section class="card">
            <h1>Bulk Discount SMS Complete</h1>

            <div class="card soft" style="border-left:5px solid #1b5e20">
                <p><b>Sent successfully:</b> {sent_count}</p>
                <p><b>Failed:</b> {failed_count}</p>
                <p class="muted">
                    Only active, unused, and not-yet-sent discount codes were included.
                </p>
            </div>

            <a class="btn" href="{url_for('admission_discounts')}">
                Back to Discount Codes
            </a>
        </section>
        """
    )


@app.post('/admission/discounts/<int:coupon_id>/delete')
def admission_discount_delete(coupon_id):

    r = require_admission_coordinator()
    if r:
        return r

    if get_setting("discounts_delete_locked", "1") == "1":
        return page(
            "Delete Locked",
            card_msg("Deleting discount codes is currently locked by high admin.")
        )

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT id, code, used_count, status
        FROM discount_coupons
        WHERE id=?
        LIMIT 1
    """, (coupon_id,))

    coupon = cur.fetchone()

    if not coupon:
        conn.close()
        return page("Not Found", card_msg("Discount code not found."))

    if int(coupon["used_count"] or 0) > 0:
        conn.close()
        return page(
            "Cannot Delete Used Code",
            card_msg("This discount code has already been used, so it cannot be deleted. It can remain as a record.")
        )

    cur.execute("""
        DELETE FROM discount_coupons
        WHERE id=?
          AND used_count=0
    """, (coupon_id,))

    conn.commit()
    conn.close()

    return redirect(request.referrer or url_for("admission_discounts"))
    
    
@app.get('/admission/referrals')
def admission_referrals():

    r = require_admission_coordinator()
    if r:
        return r

    q = request.args.get("q", "").strip()
    grade_filter = request.args.get("grade", "").strip()

    try:
        page_num = int(request.args.get("page", 1))
    except:
        page_num = 1

    if page_num < 1:
        page_num = 1

    per_page = 15
    offset = (page_num - 1) * per_page

    conn = get_db()
    cur = conn.cursor()

    ensure_all_student_referral_codes(conn)
    conn.commit()

    where = []
    params = []

    if q:
        search = f"%{q}%"

        where.append("""
            (
                s.full_name LIKE ?
                OR s.phone_whatsapp LIKE ?
                OR s.guardian_phone LIKE ?
                OR IFNULL(s.guardian_name, '') LIKE ?
                OR IFNULL(s.email, '') LIKE ?
                OR IFNULL(s.school, '') LIKE ?
                OR IFNULL(s.province, '') LIKE ?
                OR s.grade LIKE ?
                OR s.referral_code LIKE ?
                OR EXISTS (
                    SELECT 1
                    FROM enrollments e
                    JOIN subjects sub ON sub.id = e.subject_id
                    WHERE e.student_id = s.id
                      AND (
                            sub.name LIKE ?
                            OR sub.grade LIKE ?
                            OR e.month LIKE ?
                            OR e.status LIKE ?
                      )
                )
            )
        """)

        params += [
            search, search, search, search, search,
            search, search, search, search,
            search, search, search, search
        ]

    if grade_filter:
        where.append("s.grade = ?")
        params.append(grade_filter)

    where_sql = "WHERE " + " AND ".join(where) if where else ""

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM students s
        {where_sql}
    """, params)

    total_students = cur.fetchone()["c"] or 0
    total_pages = max(1, (total_students + per_page - 1) // per_page)

    if page_num > total_pages:
        page_num = total_pages
        offset = (page_num - 1) * per_page

    data_params = list(params)
    data_params.extend([per_page, offset])

    cur.execute(f"""
        SELECT
            s.id,
            s.full_name,
            s.phone_whatsapp,
            s.guardian_name,
            s.guardian_phone,
            s.grade,
            s.school,
            s.province,
            s.referral_code,
            COALESCE(s.referral_points,0) AS referral_points,
            COALESCE(s.referral_total_count,0) AS referral_total_count
        FROM students s
        {where_sql}
        ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER), s.full_name
        LIMIT ? OFFSET ?
    """, data_params)

    students = cur.fetchall()
    conn.close()

    rows = ""

    for s in students:
        points = int(s["referral_points"] or 0)

        if points >= 5:
            points_status = "<span class='chip active'>100% Reward Ready</span>"
        elif points >= 3:
            points_status = "<span class='chip pending'>50% Reward Ready</span>"
        else:
            points_status = "<span class='chip'>In Progress</span>"

        rows += f"""
        <tr>
            <td>
                <strong>{escape(s['full_name'] or 'Unnamed learner')}</strong>
                <div class="mini muted">
                    {grade_label(s['grade']) if s['grade'] else '—'}
                </div>
            </td>

            <td>
                {escape(s['phone_whatsapp'] or '—')}
                <div class="mini muted">
                    Guardian: {escape(s['guardian_name'] or '—')} | {escape(s['guardian_phone'] or '—')}
                </div>
            </td>

            <td>
                <span class="chip" style="letter-spacing:1px">
                    {escape(s['referral_code'] or '—')}
                </span>
            </td>

            <td>
                {points} / 5
                <div class="mini muted">
                    3 points = 50% | 5 points = 100%
                </div>
            </td>

            <td>{s['referral_total_count'] or 0}</td>

            <td>{points_status}</td>

            <td>
                {escape(s['school'] or '—')}
                <div class="mini muted">
                    {escape(s['province'] or '—')}
                </div>
            </td>
        </tr>
        """

    grade_options = "".join(
        f"""
        <option value="{g}" {'selected' if grade_filter == g else ''}>
            {grade_label(g)}
        </option>
        """
        for g in ["G8", "G9", "G10", "G11", "G12", "G13"]
    )

    body = f"""
    {admission_nav()}

    <section class="card">
        <h1>Student Referral Codes</h1>

        <p class="muted">
            View student referral codes, referral points, and reward progress.
            Referral points are awarded only when new learners use a valid referral code.
        </p>

        <form method="get" class="toolbar">
            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search name, phone, school, subject, grade, referral code or status">

            <select name="grade">
                <option value="">All Grades</option>
                {grade_options}
            </select>

            <button class="btn mini">Search</button>

            <a class="btn mini secondary" href="{url_for('admission_referrals')}">
                Clear
            </a>

            <a class="btn mini success" href="{url_for('admission_discounts')}">
                Go to Discount Codes
            </a>
        </form>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(students)} of {total_students} referral record(s).
        </div>

        {pagination_controls("/admission/referrals", page_num, total_pages, {"q": q, "grade": grade_filter})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Student</th>
                        <th>Contact</th>
                        <th>Referral Code</th>
                        <th>Current Points</th>
                        <th>Total Referrals</th>
                        <th>Reward Status</th>
                        <th>School / Province</th>
                    </tr>
                </thead>

                <tbody>
                    {rows or "<tr><td colspan='7'>No referral records found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/admission/referrals", page_num, total_pages, {"q": q, "grade": grade_filter})}
    </section>
    """

    return page("Admission Referrals", body)    
    
    
def build_discount_sms_body(full_name, discount, code, applies_to="ALL"):
    first_name = (full_name or "Learner").split()[0]

    if applies_to == "SUBJECT":
        applies_text = "This discount applies to the selected subject linked to the code."
    else:
        applies_text = "This discount applies to one selected subject only."

    return (
        f"EBTA: Hi {first_name}, your {discount}% discount code is {code}. "
        f"When enrolling on the EBTA Portal, enter this code in the Coupon / Referral Code section. "
        f"{applies_text} This code can only be used once."
    )    
    
    
@app.get('/admin/parents-notifications')
def admin_parents_notifications():

    r = require_admin()
    if r:
        return r

    q = request.args.get("q", "").strip()
    grade = request.args.get("grade", "").strip()
    month = request.args.get("month", "").strip() or get_admin_active_month()
    view = request.args.get("view", "all").strip()
    parent_status = request.args.get("parent_status", "").strip()

    if parent_status not in ["", "new", "returning"]:
        parent_status = ""

    if view not in ["all", "current"]:
        view = "all"

    try:
        page_num = int(request.args.get("page", 1))
    except:
        page_num = 1

    if page_num < 1:
        page_num = 1

    limit = 15
    offset = (page_num - 1) * limit

    parent_group_name = "EBTA Parents Notifications"
    parent_group_link = "https://chat.whatsapp.com/DZYMvnEl9jpEyvzxqbgwV6"

    conn = get_db()
    cur = conn.cursor()

    # ================= FILTERS =================
    from_sql = "FROM students s"
    where = [
        "s.guardian_phone IS NOT NULL",
        "TRIM(s.guardian_phone) != ''"
    ]
    params = []

    if view == "current":
        from_sql += """
            JOIN enrollments ecur
                ON ecur.student_id = s.id
               AND ecur.month = ?
        """
        params.append(month)

    if q:
        search = f"%{q}%"
        where.append("""
            (
                s.full_name LIKE ?
                OR s.guardian_name LIKE ?
                OR s.guardian_phone LIKE ?
                OR s.phone_whatsapp LIKE ?
                OR s.email LIKE ?
                OR s.school LIKE ?
                OR s.province LIKE ?
            )
        """)
        params += [
            search, search, search, search,
            search, search, search
        ]

    if grade:
        where.append("s.grade = ?")
        params.append(grade)

    where_sql = "WHERE " + " AND ".join(where)
    
    having_sql = ""

    if parent_status == "new":
        having_sql = """
            HAVING first_enrollment_month = ?
        """
    elif parent_status == "returning":
        having_sql = """
            HAVING first_enrollment_month IS NOT NULL
               AND first_enrollment_month != ?
        """

    # ================= COUNT PARENTS =================
    count_params = list(params)

    if parent_status in ["new", "returning"]:
        count_params.append(month)

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM (
            SELECT
                s.guardian_phone,
                (
                    SELECT MIN(e2.month)
                    FROM students s2
                    JOIN enrollments e2 ON e2.student_id = s2.id
                    WHERE s2.guardian_phone = s.guardian_phone
                ) AS first_enrollment_month
            {from_sql}
            {where_sql}
            GROUP BY s.guardian_phone
            {having_sql}
        ) x
    """, count_params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + limit - 1) // limit)

    if page_num > total_pages:
        page_num = total_pages
        offset = (page_num - 1) * limit

    data_params = list(params)
    data_params.extend([limit, offset])

    # ================= MAIN DATA =================
    main_params = [month] + list(params)

    if parent_status in ["new", "returning"]:
        main_params.append(month)

    main_params.extend([limit, offset])

    cur.execute(f"""
        SELECT
            COALESCE(NULLIF(MIN(s.guardian_name), ''), 'Parent/Guardian') AS guardian_name,
            s.guardian_phone,

            GROUP_CONCAT(DISTINCT s.full_name) AS learner_names,
            GROUP_CONCAT(DISTINCT s.grade) AS grades,
            GROUP_CONCAT(DISTINCT s.school) AS schools,
            GROUP_CONCAT(DISTINCT s.province) AS provinces,
            COUNT(DISTINCT s.id) AS learner_count,

            (
                SELECT MIN(e2.month)
                FROM students s2
                JOIN enrollments e2 ON e2.student_id = s2.id
                WHERE s2.guardian_phone = s.guardian_phone
            ) AS first_enrollment_month,

            (
                SELECT COUNT(DISTINCT e3.id)
                FROM students s3
                JOIN enrollments e3 ON e3.student_id = s3.id
                WHERE s3.guardian_phone = s.guardian_phone
                  AND e3.month = ?
            ) AS current_month_enrollments

        {from_sql}
        {where_sql}
        GROUP BY s.guardian_phone
        {having_sql}
        ORDER BY guardian_name, s.guardian_phone
        LIMIT ? OFFSET ?
    """, main_params)

    rows = cur.fetchall()
    conn.close()

    trs = ""

    for p in rows:
        parent_name = p["guardian_name"] or "Parent/Guardian"
        parent_phone = p["guardian_phone"] or ""
        learner_names = p["learner_names"] or "Learner"
        grades = p["grades"] or "—"
        schools = p["schools"] or "—"
        provinces = p["provinces"] or "—"
        first_month = p["first_enrollment_month"] or ""
        current_month_enrollments = p["current_month_enrollments"] or 0

        if first_month == month:
            parent_status_label = "New Parent"
            parent_status_html = "<span class='chip active'>New Parent</span>"
        else:
            parent_status_label = "Returning Parent"
            parent_status_html = "<span class='chip pending'>Returning Parent</span>"

        month_badge = ""

        if current_month_enrollments:
            month_badge = f"""
            <div class="mini muted" style="margin-top:4px">
                {current_month_enrollments} enrollment(s) in {escape(month)}
            </div>
            """
        else:
            month_badge = f"""
            <div class="mini muted" style="margin-top:4px">
                No enrollment in {escape(month)}
            </div>
            """

        wa_number = whatsapp_number(parent_phone)

        message = (
            f"Good day {parent_name},\n\n"
            f"You are kindly invited to join the EBTA Parents Notifications WhatsApp group.\n\n"
            f"Group name: {parent_group_name}\n"
            f"Group link: {parent_group_link}\n\n"
            f"This group will be used to share important EBTA updates, learner notices, schedules, reminders, and parent-related communication.\n\n"
            f"Kind regards,\n"
            f"EBTA Admin Team"
        )

        if wa_number:
            wa_link = f"https://wa.me/{wa_number}?{urlencode({'text': message})}"
            action_btn = f"""
            <a class="btn mini success"
               target="_blank"
               href="{wa_link}">
                Send WhatsApp Invite
            </a>
            """
        else:
            action_btn = "<span class='mini muted'>Invalid number</span>"

        trs += f"""
        <tr>
            <td>
                <strong>{escape(parent_name)}</strong>
                <div class="mini muted">
                    Learner(s): {escape(learner_names)}
                </div>
            </td>

            <td>
                {parent_status_html}
                <div class="mini muted" style="margin-top:4px">
                    First month: {escape(first_month or '—')}
                </div>
                {month_badge}
            </td>

            <td>
                {escape(parent_phone)}
                <div class="mini muted">
                    WhatsApp: {escape(wa_number or '—')}
                </div>
            </td>

            <td>{escape(grades)}</td>

            <td>
                {escape(schools)}
                <div class="mini muted">{escape(provinces)}</div>
            </td>

            <td>{p['learner_count']}</td>

            <td>{action_btn}</td>
        </tr>
        """

    view_options = f"""
        <option value="all" {'selected' if view == 'all' else ''}>All Parents</option>
        <option value="current" {'selected' if view == 'current' else ''}>Current Month Parents Only</option>
    """
    
    parent_status_options = f"""
        <option value="" {'selected' if parent_status == '' else ''}>All Statuses</option>
        <option value="new" {'selected' if parent_status == 'new' else ''}>New Parents</option>
        <option value="returning" {'selected' if parent_status == 'returning' else ''}>Returning Parents</option>
    """

    body = f"""
    {admin_nav()}

    <section class="card">
        <h1>Parents Notifications</h1>

        <p class="muted">
            View parent or guardian contact details, check whether they are new or returning,
            and send them the EBTA Parents Notifications WhatsApp group invite.
        </p>

        <div class="card soft" style="border-left:5px solid #25D366;margin-bottom:14px">
            <h2>Group Details</h2>

            <p>
                <strong>Group Name:</strong> {escape(parent_group_name)}<br>
                <strong>Group Link:</strong>
                <a class="links" target="_blank" href="{parent_group_link}">
                    {parent_group_link}
                </a>
            </p>
        </div>

        <form method="get" class="toolbar">

            <input type="month"
                   name="month"
                   value="{escape(month)}"
                   title="Select month">

            <select name="view">
                {view_options}
            </select>
            
            <select name="parent_status">
                {parent_status_options}
            </select>

            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search parent, learner, phone, school or province">

            <select name="grade">
                <option value="">All Grades</option>
                {''.join(
                    f"<option value='{g}' {'selected' if grade==g else ''}>{grade_label(g)}</option>"
                    for g in ["G8","G9","G10","G11","G12","G13"]
                )}
            </select>

            <button class="btn mini">Search</button>

            <a class="btn mini secondary" href="{url_for('admin_parents_notifications')}">
                Clear
            </a>

            <a class="btn mini success"
               href="{url_for('admin_parents_notifications')}?{urlencode({'month': get_admin_active_month(), 'view': 'current'})}">
                Current Month Parents
            </a>
        </form>

        <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin:10px 0">

            <div class="mini muted">
                Showing {len(rows)} of {total} parent contact record(s)
                for <b>{pretty_month_label(month)}</b>.
            </div>

            <a class="btn mini success"
               href="{url_for('admin_parents_notifications_export')}?{urlencode({'q': q, 'grade': grade, 'month': month, 'view': view, 'parent_status': parent_status})}">
                Export Parents Excel
            </a>

        </div>

        {pagination_controls("/admin/parents-notifications", page_num, total_pages, {"q": q, "grade": grade, "month": month, "view": view, "parent_status": parent_status})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Parent / Learner</th>
                        <th>Status</th>
                        <th>WhatsApp Number</th>
                        <th>Grade(s)</th>
                        <th>School / Province</th>
                        <th>Learners</th>
                        <th>Action</th>
                    </tr>
                </thead>

                <tbody>
                    {trs or "<tr><td colspan='7'>No parent contacts found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/admin/parents-notifications", page_num, total_pages, {"q": q, "grade": grade, "month": month, "view": view, "parent_status": parent_status})}
    </section>
    """

    return page("Parents Notifications", body)


